public final class SkillLevelTask extends Task
{
    private Skill skill;

    @SerializedName("level")
    private int targetSkillLevel;
    private int currentSkillLevel;

    @Override
    public String getDisplayName()
    {
        return String.format("Reach level %d %s", targetSkillLevel, skill.getName());
    }

    @Override
    public String toString()
    {
        return String.format("%s %s", targetSkillLevel, skill.getName());
    }

    @Override
    public TaskType getType()
    {
        return TaskType.SKILL_LEVEL;
    }

    /**
     * Re-evaluate the player's level in the skill and update the Task.status field.
     * Safe to call on login and whenever relevant varbits/varps change.
     */
    public void refreshStatus(final Client client)
    {
        if (client == null || skill == null)
        {
            return;
        }


        currentSkillLevel = client.getRealSkillLevel(skill);


        if(hasReachedTargetLevel())
        {
            setStatus(Status.COMPLETED);
        }
        // This covers cases where players log into a separate character that no longer meets the task requirements
        else {
            setStatus(Status.NOT_STARTED);
        }
    }

    /**
     * Whether the player has reached the target level for this task.
     * @return <ul>
     *     <li>{@code true} - Target level <b>HAS</b> been reached</li>
     *     <li>{@code false} - Target level <b>HAS NOT</b> been reached</li>
     * </ul>
     */
    public boolean hasReachedTargetLevel()
    {
        return (currentSkillLevel >= targetSkillLevel);
    }

    /**
     * Whether the player would reach the target level for this task given the level provided.
     * @param level The level to check against
     * @return <ul>
     *     <li>{@code true} - Target level <b>HAS</b> been reached</li>
     *     <li>{@code false} - Target level <b>HAS NOT</b> been reached</li>
     * </ul>
     */
    public boolean wouldReachTargetLevel(int level)
    {
        return (level >= targetSkillLevel);
    }
}

package com.darkforge317.goaltracker.models.task;

import com.darkforge317.goaltracker.models.enums.Status;
import com.darkforge317.goaltracker.models.enums.TaskType;
import com.google.gson.annotations.SerializedName;
import lombok.Getter;
import lombok.Setter;
import lombok.experimental.SuperBuilder;
import net.runelite.api.Client;
import net.runelite.api.Skill;

@Getter
@Setter
@SuperBuilder
/**
 * Task representing earning a target XP amount in a skill.
 * Stores the RuneLite Skill and required XP.
 */
public final class SkillXpTask extends Task
{
    private Skill skill;

    @SerializedName("xp")
    private int targetSkillXp;
    private int currentSkillXp;

    /** Whole virtual level-field target; null for fractional levels and XP input. */
    private Double targetLevel;

    private String targetTitle()
    {
        return targetLevel == null ? String.format("%d %s XP", targetSkillXp, skill.getName())
            : String.format("%s %s", java.math.BigDecimal.valueOf(targetLevel).stripTrailingZeros().toPlainString(), skill.getName());
    }

    @Override
    public String toString()
    {
        return targetTitle();
    }

    @Override
    public String getDisplayName()
    {
        return targetTitle();
    }

    @Override
    public TaskType getType()
    {
        return TaskType.SKILL_XP;
    }

    /**
     * Re-evaluate the player's Xp in the skill and update the Task.status field.
     * Safe to call on login and whenever relevant varbits/varps change.
     */
    public void refreshStatus(final Client client)
    {
        if (client == null || skill == null)
        {
            return;
        }

        currentSkillXp = client.getSkillExperience(skill);

        if(hasReachedTargetXp())
        {
            setStatus(Status.COMPLETED);
        }
        // This covers cases where players log into a separate character that no longer meets the task requirements
        else {
            setStatus(Status.NOT_STARTED);
        }
    }

    /**
     * Whether the player has reached the target Xp for this task.
     * @return <ul>
     *     <li>{@code true} - Target Xp <b>HAS</b> been reached</li>
     *     <li>{@code false} - Target Xp <b>HAS NOT</b> been reached</li>
     * </ul>
     */
    public boolean hasReachedTargetXp()
    {
        return (currentSkillXp >= targetSkillXp);
    }

    /**
     * Whether the player would reach the target Xp for this task given the xp provided.
     * @param xp The Xp value to check against
     * @return <ul>
     *     <li>{@code true} - Target Xp <b>HAS</b> been reached</li>
     *     <li>{@code false} - Target Xp <b>HAS NOT</b> been reached</li>
     * </ul>
     */
    public boolean wouldReachTargetXp(int xp)
    {
        return (xp >= targetSkillXp);
    }
}

package com.darkforge317.goaltracker.models.task;

import com.google.gson.annotations.SerializedName;
import com.darkforge317.goaltracker.models.enums.Status;
import com.darkforge317.goaltracker.models.enums.TaskType;
import lombok.Builder;
import lombok.Getter;
import lombok.Setter;
import lombok.experimental.SuperBuilder;
import java.util.UUID;

@Getter
@Setter
@SuperBuilder
/**
 * Base class for all goal tasks.
 * Provides status tracking, indent level management, and type identification.
 */
public abstract class Task
{
    @Builder.Default
    @SerializedName("task_id")
    private String taskId = UUID.randomUUID().toString();

    @SerializedName("parent_task_id")
    private String parentTaskId;

    @Builder.Default
    @SerializedName(value = "status", alternate = {"previous_result"})
    private Status status = Status.NOT_STARTED;

    @Builder.Default
    @SerializedName("has_been_notified")
    private boolean notified = false;

    @Builder.Default
    @SerializedName("indent_level")
    private int indentLevel = 0;

    @Builder.Default
    @SerializedName("collapsed")
    private boolean collapsed = false;

    // The maximum indent we'll allow. Currently, 15 levels in total (0-14)
    public static final int MAX_INDENT_LEVEL = 14;

    public boolean isDone() {
        return Status.COMPLETED.equals(this.status);
    }

    public void indent() {
        if (indentLevel >= MAX_INDENT_LEVEL) return;

        indentLevel += 1;
    }

    public void unindent() {
        if (isNotIndented()) return;

        indentLevel -= 1;
    }

    public boolean isIndented() {
        return indentLevel > 0;
    }

    public boolean isNotIndented() {
        return !isIndented();
    }

    public boolean isFullyIndented() {
        return indentLevel >= MAX_INDENT_LEVEL;
    }

    public boolean isNotFullyIndented() {
        return !isFullyIndented();
    }

    public Status getStatus()
    {
        // If the task was built without an explicit status,
        // ensure the application reads it safely as NOT_STARTED.
        if (this.status == null)
        {
            return Status.NOT_STARTED;
        }
        return this.status;
    }


    @Override
    abstract public String toString();

    /**
     * Returns a human-readable name for the task.
     */
    public abstract String getDisplayName();

    abstract public TaskType getType();
}

