/**
 * Reads changelog data bundled as plugin resources under /changelogs/. Plugin Hub jars
 * are not unpacked on disk, so this never lists a directory - it reads a small manifest
 * (versions.txt) that declares which versions exist, one per line in any order (versions
 * are compared numerically, not by file position - see README-changelogs.md for the
 * recommended human-readable ordering convention), then loads each version's own
 * markdown file from /changelogs/logs/ by its exact known name (dots converted to
 * hyphens, e.g. "2.1.1" -> logs/v2-1-1.md).
 */
public final class ChangelogService
{
    private static final String CHANGELOG_ROOT = "/changelogs/";
    private static final String LOGS_SUBDIR = CHANGELOG_ROOT + "logs/";
    private static final String VERSIONS_MANIFEST = CHANGELOG_ROOT + "versions.txt";

    public static final class ChangelogEntry
    {
        private final String version;
        private final String markdown;

        public ChangelogEntry(String version, String markdown)
        {
            this.version = version;
            this.markdown = markdown;
        }

        public String getVersion() { return version; }
        public String getMarkdown() { return markdown; }
    }

    /**
     * All changelog entries, newest first, regardless of what order versions.txt lists
     * them in - versions are compared numerically. A version listed in the manifest
     * whose .md file is missing/unreadable is silently skipped rather than producing
     * a broken entry.
     */
    public List<ChangelogEntry> getAllEntries()
    {
        List<ChangelogEntry> entries = new ArrayList<>();
        List<String> versions = new ArrayList<>(getAllVersions());
        versions.sort(ChangelogService::compareVersionNumbers);

        for (int i = versions.size() - 1; i >= 0; i--)
        {
            String version = versions.get(i);
            String markdown = getChangelogMarkdown(version);
            if (markdown != null)
            {
                entries.add(new ChangelogEntry(version, markdown));
            }
        }
        return entries;
    }

    /** The numerically highest version among those declared in versions.txt, or null if none. */
    public ChangelogEntry getNewestEntry()
    {
        List<ChangelogEntry> entries = getAllEntries();
        return entries.isEmpty() ? null : entries.get(0);
    }

    public boolean isNewestEntry(ChangelogEntry entry)
    {
        ChangelogEntry newestEntry = getNewestEntry();
        if (newestEntry == null || entry == null) return false;

        return compareVersionNumbers(newestEntry.getVersion(), entry.getVersion()) == 0;
    }

    /**
     * Raw version strings (e.g. "2.1.1"), in whatever order versions.txt lists them.
     * Returns an empty list if the manifest is missing or unreadable.
     */
    private List<String> getAllVersions()
    {
        List<String> versions = new ArrayList<>();
        try (InputStream in = ChangelogService.class.getResourceAsStream(VERSIONS_MANIFEST))
        {
            if (in == null) return versions;
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
            {
                String line;
                while ((line = reader.readLine()) != null)
                {
                    line = line.trim();
                    if (!line.isEmpty()) versions.add(line);
                }
            }
        }
        catch (IOException e)
        {
            // Leave versions empty; callers treat this the same as "no changelogs bundled"
        }
        return versions;
    }

    /**
     * Raw markdown content for a given version (e.g. "2.1.1" -> /changelogs/logs/v2-1-1.md),
     * or null if the resource is missing or unreadable.
     */
    private String getChangelogMarkdown(String version)
    {
        String fileName = "v" + version.replace('.', '-') + ".md";
        String path = LOGS_SUBDIR + fileName;
        try (InputStream in = ChangelogService.class.getResourceAsStream(path))
        {
            if (in == null) return null;
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
            {
                StringBuilder sb = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null)
                {
                    sb.append(line).append('\n');
                }
                return sb.toString();
            }
        }
        catch (IOException e)
        {
            return null;
        }
    }

    /**
     * Numerically compares two dotted version strings component by component
     * (e.g. "2.1.10" > "2.1.9", unlike a plain string comparison). A missing or
     * non-numeric component is treated as 0.
     */
    private static int compareVersionNumbers(String a, String b)
    {
        // Split the version numbers apart. (e.g. "10.2.4" -> ["10","2","4"])
        String[] partsA = a.split("\\.");
        String[] partsB = b.split("\\.");
        int len = Math.max(partsA.length, partsB.length);

        // For each segment in the version string, left to right
        for (int i = 0; i < len; i++)
        {
            // Is there a number in this segment? What is it?
            int numA = i < partsA.length ? parseIntSafe(partsA[i]) : 0;
            int numB = i < partsB.length ? parseIntSafe(partsB[i]) : 0;

            // If one number is larger than the other
            if (numA != numB) {
                // Return whether numA is larger (>0) or smaller (<0)
                return Integer.compare(numA, numB);
            }
        }
        return 0;
    }

    /**
     * Compares two dotted version strings.
     * Returns the newer of the two version strings.
     * (e.g. "2.1.10" > "2.1.9", so "2.1.10" would be returned)
     */
    private static String getNewerVersion(String a, String b)
    {
        // Exit if we don't have two strings
        if (a == null) return b;
        if (b == null) return a;

        // Return the newer of the two version strings
        return compareVersionNumbers(a, b) >= 0 ? a : b;
    }

    private static int parseIntSafe(String s)
    {
        if (s == null) return 0;
        try { return Integer.parseInt(s.trim()); }
        catch (NumberFormatException e) { return 0; }
    }
}

package com.darkforge317.goaltracker.services;

import net.runelite.client.input.KeyListener;

import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.awt.event.KeyEvent;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Tracks Shift key state within the RuneLite client window via KeyManager
 * (client-scoped, plugin-hub approved) rather than java.awt.KeyboardFocusManager
 * (JVM-wide, disallowed). UI components subscribe to be notified on change.
 */
@Singleton
public class KeyInputService implements KeyListener
{
    private volatile boolean shiftDown = false;
    private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

    public boolean isShiftDown() { return shiftDown; }

    public void addListener(Runnable listener) { listeners.add(listener); }
    public void removeListener(Runnable listener) { listeners.remove(listener); }

    @Override public void keyTyped(KeyEvent e) { }

    @Override
    public void keyPressed(KeyEvent e)
    {
        if (e.getKeyCode() == KeyEvent.VK_SHIFT && !shiftDown)
        {
            shiftDown = true;
            fireChanged();
        }
    }

    @Override
    public void keyReleased(KeyEvent e)
    {
        if (e.getKeyCode() == KeyEvent.VK_SHIFT && shiftDown)
        {
            shiftDown = false;
            fireChanged();
        }
    }

    private void fireChanged()
    {
        SwingUtilities.invokeLater(() -> listeners.forEach(Runnable::run));
    }
}

package com.darkforge317.goaltracker.services;

import com.darkforge317.goaltracker.GoalTrackerPlugin;
import com.darkforge317.goaltracker.ui.ChangelogListPanel;
import com.darkforge317.goaltracker.ui.ChangelogPanel;
import com.darkforge317.goaltracker.ui.GoalTrackerPanel;
import com.darkforge317.goaltracker.ui.Refreshable;
import com.google.inject.Inject;
import net.runelite.client.ui.PluginPanel;

import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.Component;


public class PanelService extends PluginPanel {
    private final GoalTrackerPlugin plugin;
    private boolean goalsChangedListenerRegistered = false;

    // In PanelService.java
    @Inject
    public PanelService(GoalTrackerPlugin plugin)
    {
        super(false); // Explicitly required for custom layouts
        this.plugin = plugin;

        setLayout(new BorderLayout()); // Anchors layout components precisely
        setBorder(null);
    }


    public void showHome()
    {
        removeAll();
        GoalTrackerPanel panel = new GoalTrackerPanel(this, plugin, plugin.getGoalManager());
        panel.onGoalUpdated(plugin::onGoalUpdatedCallback);
        panel.onTaskAdded(plugin::onTaskAddedCallback);
        panel.onTaskUpdated(plugin::onTaskUpdatedCallback);
        add(panel, BorderLayout.CENTER);
        revalidate();
        repaint();
    }

    public void showGoalPanel()
    {

    }

    public void showChangelogListPanel()
    {
        removeAll();
        ChangelogListPanel panel = new ChangelogListPanel(this, plugin);
        add(panel, BorderLayout.CENTER);
        revalidate();
        repaint();
    }

    public void showChangelogPanel(ChangelogService.ChangelogEntry entry, boolean isNewUpdate, boolean createdByChangelogListPanel)
    {
        removeAll();
        ChangelogPanel panel = new ChangelogPanel(this, plugin, entry, isNewUpdate, createdByChangelogListPanel);
        add(panel, BorderLayout.CENTER);
        revalidate();
        repaint();
    }

    /**
     * Refreshes whatever content is currently displayed, if it's Refreshable
     * Callers don't need to know which panel happens to be showing.
     */
    public void refreshCurrent()
    {
        for (Component component : getComponents())
        {
            if (component instanceof Refreshable)
            {
                ((Refreshable) component).refresh();
            }
        }
    }

    public void registerGoalsChangedListener()
    {
        plugin.getGoalManager().addGoalsChangedListener(() -> SwingUtilities.invokeLater(this::refreshCurrent));
    }
}

package com.darkforge317.goaltracker.services;

import com.darkforge317.goaltracker.GoalTrackerPlugin;
import com.darkforge317.goaltracker.models.task.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.AsyncBufferedImage;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;

/**
 * Resolves small 16x16 icons for tasks (items, skills, quests, manual checks).
 */
@Singleton
public final class TaskIconService
{
    private static final int ICON_SIZE = 16;

    public static final ImageIcon CROSS_MARK_ICON;
    public static final ImageIcon CHECK_MARK_ICON;
    public static final ImageIcon QUEST_ICON;
    public static final ImageIcon QUEST_COMPLETE_ICON;
    public static final ImageIcon UNKNOWN_ICON;
    private static final BufferedImage COMBAT_LEVEL_IMAGE;

    static
    {
        CROSS_MARK_ICON = new ImageIcon(
            ImageUtil.loadImageResource(GoalTrackerPlugin.class, "/cross_mark.png")
        );
        CHECK_MARK_ICON = new ImageIcon(
            ImageUtil.loadImageResource(GoalTrackerPlugin.class, "/check_mark.png")
        );
        QUEST_ICON = new ImageIcon(
            ImageUtil.loadImageResource(GoalTrackerPlugin.class, "/quest_icon.png")
        );
        QUEST_COMPLETE_ICON = new ImageIcon(
            ImageUtil.loadImageResource(GoalTrackerPlugin.class, "/quest_complete.png")
        );
        UNKNOWN_ICON = new ImageIcon(
            ImageUtil.loadImageResource(GoalTrackerPlugin.class, "/question_mark.png")
        );
        COMBAT_LEVEL_IMAGE = ImageUtil.loadImageResource(GoalTrackerPlugin.class, "/combat_level_icon.png");
    }

    @Inject private ItemManager itemManager;
    @Inject private SkillIconManager skillIconManager;

    public ImageIcon get(Task task)
    {
        if (task instanceof ManualTask)
        {
            return get((ManualTask) task);
        }
        if (task instanceof QuestTask)
        {
            return get((QuestTask) task);
        }

        BufferedImage image = null;
        if (task instanceof SkillLevelTask)
        {
            image = get((SkillLevelTask) task);
        }
        else if (task instanceof SkillXpTask)
        {
            image = get((SkillXpTask) task);
        }
        else if (task instanceof ItemTask)
        {
            image = get((ItemTask) task);
        }
        else if (task instanceof CombatLevelTask)
        {
            image = COMBAT_LEVEL_IMAGE;
        }
        else if (task instanceof QuestPointsTask)
        {
            return QUEST_ICON;
        }

        if (image != null)
        {
            return iconify(image);
        }

        return UNKNOWN_ICON;
    }

    public ImageIcon get(ManualTask task)
    {
        return task.isDone() ? CHECK_MARK_ICON : CROSS_MARK_ICON;
    }

    public BufferedImage get(SkillLevelTask task)
    {
        return skillIconManager.getSkillImage(task.getSkill());
    }

    public BufferedImage get(SkillXpTask task)
    {
        return skillIconManager.getSkillImage(task.getSkill());
    }

    public ImageIcon get(QuestTask task)
    {
        return task.isDone() ? QUEST_COMPLETE_ICON : QUEST_ICON;
    }

    public BufferedImage get(ItemTask task)
    {
        if (task.getCachedIcon() == null)
        {
            task.setCachedIcon(itemManager.getImage(task.getItemId()));
        }
        return task.getCachedIcon();
    }

    /** Bind the label to an image that may still be loading on the game thread. */
    public void updateIcon(Task task, JLabel label)
    {
        Object request = new Object();
        label.putClientProperty(TaskIconService.class, request);
        label.setIcon(get(task));
        if (task instanceof ItemTask)
        {
            BufferedImage image = ((ItemTask) task).getCachedIcon();
            if (image instanceof AsyncBufferedImage)
            {
                ((AsyncBufferedImage) image).onLoaded(() -> SwingUtilities.invokeLater(() -> {
                    if (label.getClientProperty(TaskIconService.class) == request)
                    {
                        label.setIcon(iconify(image));
                    }
                }));
            }
        }
    }

    private ImageIcon iconify(BufferedImage img)
    {
        Image scaled = img.getScaledInstance(ICON_SIZE, ICON_SIZE, Image.SCALE_SMOOTH);
        return new ImageIcon(scaled);
    }
}

package com.darkforge317.goaltracker.services;

import com.darkforge317.goaltracker.ItemCache;
import com.darkforge317.goaltracker.models.enums.Status;
import com.darkforge317.goaltracker.models.task.CombatLevelTask;
import com.darkforge317.goaltracker.models.task.*;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.VarPlayer;
import net.runelite.api.events.StatChanged;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Updates task status based on current client state and events.
 */
@Singleton
public final class TaskUpdateService
{
    @Inject private Client client;
    @Inject private ItemCache itemCache;

    /**
     * Dispatch update for a generic task, returning true if status/values changed.
     */
    public boolean update(Task task)
    {
        switch (task.getType())
        {
            case SKILL_LEVEL: return update((SkillLevelTask) task);
            case SKILL_XP:    return update((SkillXpTask) task);
            case COMBAT_LEVEL: return update((CombatLevelTask) task);
            case QUEST_POINTS: return update((QuestPointsTask) task);
            case QUEST:       return update((QuestTask) task);
            case ITEM:        return update((ItemTask) task);
            default:          return false;
        }
    }

    // -------------------- Skill Level --------------------

    /** Returns true if the cached combat level or task status changed. */
    public boolean update(CombatLevelTask task)
    {
        if (client.getGameState() != GameState.LOGGED_IN || !client.isClientThread())
        {
            return false;
        }
        Player player = client.getLocalPlayer();
        if (player == null)
        {
            return false;
        }
        double combatLevel = Experience.getCombatLevelPrecise(
            client.getRealSkillLevel(Skill.ATTACK),
            client.getRealSkillLevel(Skill.STRENGTH),
            client.getRealSkillLevel(Skill.DEFENCE),
            client.getRealSkillLevel(Skill.HITPOINTS),
            client.getRealSkillLevel(Skill.MAGIC),
            client.getRealSkillLevel(Skill.RANGED),
            client.getRealSkillLevel(Skill.PRAYER));
        return update(task, combatLevel);
    }

    /** Update from a combat level already read on the client thread. */
    public boolean update(CombatLevelTask task, double combatLevel)
    {
        double oldCombatLevel = task.getCurrentCombatLevel();
        Status oldStatus = task.getStatus();
        task.setCurrentCombatLevel(combatLevel);
        task.setStatus(task.wouldReachTargetLevel(combatLevel) ? Status.COMPLETED : Status.NOT_STARTED);
        return oldCombatLevel != task.getCurrentCombatLevel() || oldStatus != task.getStatus();
    }

    /** Read the current Quest point total from the logged-in client. */
    @SuppressWarnings("deprecation")
    public boolean update(QuestPointsTask task)
    {
        if (client.getGameState() != GameState.LOGGED_IN || !client.isClientThread())
        {
            return false;
        }
        return update(task, client.getVarpValue(VarPlayer.QUEST_POINTS));
    }

    /** Update from the Quest point total already read on the client thread. */
    public boolean update(QuestPointsTask task, int questPoints)
    {
        int oldQuestPoints = task.getCurrentQuestPoints();
        Status oldStatus = task.getStatus();
        task.setCurrentQuestPoints(Math.max(0, questPoints));
        task.setStatus(task.wouldReachTarget(task.getCurrentQuestPoints())
            ? Status.COMPLETED
            : (task.getCurrentQuestPoints() > 0 ? Status.IN_PROGRESS : Status.NOT_STARTED));
        return oldQuestPoints != task.getCurrentQuestPoints() || oldStatus != task.getStatus();
    }

    /** Returns true if an update has occurred. */
    public boolean update(SkillLevelTask task)
    {
        if (client.getGameState() != GameState.LOGGED_IN || !client.isClientThread())
        {
            return false;
        }
        return update(task, client.getRealSkillLevel(task.getSkill()));
    }

    /** Returns true if an update has occurred (event-driven). */
    public boolean update(SkillLevelTask task, StatChanged event)
    {
        if (event.getSkill() != task.getSkill())
        {
            return false;
        }
        return update(task, event.getLevel());
    }

    /** Returns true if an update has occurred given a specific level. */
    public boolean update(SkillLevelTask task, int level)
    {
        final Status oldStatus = task.getStatus();
        task.setCurrentSkillLevel(level);
        task.setStatus(level >= task.getTargetSkillLevel() ? Status.COMPLETED : Status.NOT_STARTED);
        return oldStatus != task.getStatus();
    }

    // -------------------- Skill XP --------------------

    /** Returns true if an update has occurred. */
    public boolean update(SkillXpTask task)
    {
        if (client.getGameState() != GameState.LOGGED_IN || !client.isClientThread())
        {
            return false;
        }
        return update(task, client.getSkillExperience(task.getSkill()));
    }

    /** Returns true if an update has occurred (event-driven). */
    public boolean update(SkillXpTask task, StatChanged event)
    {
        if (event.getSkill() != task.getSkill())
        {
            return false;
        }
        return update(task, event.getXp());
    }

    /** Returns true if an update has occurred given a specific XP value. */
    public boolean update(SkillXpTask task, int xp)
    {
        final Status oldStatus = task.getStatus();

        // Store the live player experience in the task's cache
        task.setCurrentSkillXp(xp);

        task.setStatus(xp >= task.getTargetSkillXp() ? Status.COMPLETED : Status.NOT_STARTED);
        return oldStatus != task.getStatus();
    }

    // -------------------- Quest --------------------

    /** Returns true if an update has occurred. */
    public boolean update(QuestTask task)
    {
        if (client.getGameState() != GameState.LOGGED_IN || !client.isClientThread())
        {
            return false;
        }
        final Status oldStatus = task.getStatus();
        task.setStatus(Status.fromQuestState(task.getQuest().getState(client)));
        return oldStatus != task.getStatus();
    }

    // -------------------- Item --------------------

    /** Returns true if an update has occurred. */
    public boolean update(ItemTask task)
    {
        final int oldAcquired = task.getAcquired();
        final Status oldStatus = task.getStatus();

        task.setAcquired(Math.min(itemCache.getTotalQuantity(task.getItemId()), task.getQuantity()));

        task.setStatus(
            task.getAcquired() >= task.getQuantity()
                ? Status.COMPLETED
                : (task.getAcquired() > 0 ? Status.IN_PROGRESS : Status.NOT_STARTED)
        );

        return oldAcquired != task.getAcquired() || oldStatus != task.getStatus();
    }
}

package com.darkforge317.goaltracker.ui;

import com.darkforge317.goaltracker.GoalTrackerPlugin;
import com.darkforge317.goaltracker.utils.ScrollSpeedUtils;
import com.darkforge317.goaltracker.services.ChangelogService;
import com.darkforge317.goaltracker.services.ChangelogService.ChangelogEntry;
import com.darkforge317.goaltracker.services.PanelService;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.JTextPane;
import javax.swing.border.EmptyBorder;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JEditorPane;
import javax.swing.JPanel;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import java.awt.*;
import java.util.List;

//region LAYOUT HIERARCHY
/*   ChangelogListPanel (JPanel, BorderLayout)
     │
     ├── topSection (JPanel, BorderLayout)
     │   ├── headerBar (JPanel, GridLayout)
     │   │   └── backButton (JButton)
     │   └── titleSection (JPanel, Vertical BoxLayout)
     │       └── titleLabel (JLabel)
     └── scrollPane (JScrollPane)
         └── JViewport (Internal Viewport Area)
             └── contentPane (JTextPane)
                 │<──<──<──<──<──<──<──<──<──<──<──<──<──<──<──<──<──<──<──<──<──<──┐
                 │── [Element N] ComponentView ── changelogEntryButton (JButton)    │
                 │── [Text Context] "\n" (Line Break)                               │
                 └──>──>─ LOOP THROUGH ALL CHANGELOG ENTRIES ─>──>──>──>──>──>──>──>┘
*/
//endregion
@Slf4j
public class ChangelogListPanel extends JPanel
{
    private final PanelService panelService;
    private static final int CONTENT_PADDING = 8;
    private ChangelogService changelogService = new ChangelogService();
    private List<ChangelogService.ChangelogEntry> changelogEntries = changelogService.getAllEntries();

    public ChangelogListPanel(PanelService panelService, GoalTrackerPlugin plugin)
    {
        super(new BorderLayout());
        this.panelService = panelService;
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel headerBar = new JPanel(new GridLayout(1, 2, 4, 0));
        headerBar.setBorder(new EmptyBorder(4, 4, 4, 4));
        JButton backButton = new JButton("Back");
        backButton.setToolTipText("Return to Goal Tracker home");
        backButton.addActionListener(e -> onBackButtonClicked());
        headerBar.add(backButton);

        JLabel titleLabel = new JLabel("All Changelogs");
        titleLabel.setFont(FontManager.getRunescapeBoldFont());
        titleLabel.setForeground(ColorScheme.BRAND_ORANGE);
        titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

        JPanel titleSection = new JPanel();
        titleSection.setLayout(new BoxLayout(titleSection, BoxLayout.Y_AXIS));
        titleSection.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titleSection.setBorder(new EmptyBorder(8, 8, 4, 8));
        titleSection.add(titleLabel);

        JPanel topSection = new JPanel(new BorderLayout());
        topSection.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topSection.add(headerBar, BorderLayout.NORTH);
        topSection.add(titleSection, BorderLayout.CENTER);

        JTextPane contentPane = new JTextPane()
        {
            @Override
            public boolean getScrollableTracksViewportWidth()
            {
                return true;
            }
        };
        contentPane.setContentType("text/html");
        contentPane.setEditable(false);
        contentPane.setFocusable(false);
        contentPane.setOpaque(false);
        contentPane.setBorder(new EmptyBorder(0, CONTENT_PADDING, CONTENT_PADDING, CONTENT_PADDING));
        contentPane.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        for (ChangelogService.ChangelogEntry entry : changelogEntries) {
            JButton changelogEntryButton = new JButton("Version " + entry.getVersion());
            changelogEntryButton.setToolTipText("View changelog for version " + entry.getVersion());
            changelogEntryButton.setBackground(ColorScheme.DARK_GRAY_COLOR);
            changelogEntryButton.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            changelogEntryButton.addActionListener( e -> onChangelogEntryClicked(entry));

            // Explicitly clamp the size so the HTML layout engine respects it
            changelogEntryButton.setAlignmentX(Component.CENTER_ALIGNMENT);
            changelogEntryButton.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, 30));

            // Force insert directly into the text layout flow
            contentPane.setCaretPosition(contentPane.getDocument().getLength());
            contentPane.insertComponent(changelogEntryButton);

            // Insert a native HTML line break so the buttons stack vertically
            try {
                contentPane.getDocument().insertString(contentPane.getDocument().getLength(), "\n", null);
            } catch (Exception e) {
                log.error("Failed to insert line break after changelog entry button", e);
            }
        }

        JScrollPane scrollPane = new JScrollPane(contentPane);
        scrollPane.setBorder(BorderFactory.createEmptyBorder());
        scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        ScrollSpeedUtils.configure(scrollPane, plugin.getConfig());

        add(topSection, BorderLayout.NORTH);
        add(scrollPane, BorderLayout.CENTER);
    }

    private void onChangelogEntryClicked(ChangelogEntry entry)
    {
        Boolean isNewestEntry = changelogService.isNewestEntry(entry);

        panelService.showChangelogPanel(entry, isNewestEntry, true);
    }

    private void onBackButtonClicked(){
        panelService.showHome();
    }
}

