public class ChangelogPanel extends JPanel
{
    private final PanelService panelService;
    private final GoalTrackerPlugin plugin;
    private final boolean createdByChangelogListPanel;
    private static final int CONTENT_PADDING = 8;
    private final ChangelogService.ChangelogEntry entry;

    public ChangelogPanel(PanelService panelService, GoalTrackerPlugin plugin, ChangelogService.ChangelogEntry entry, boolean isNewUpdate, boolean createdByChangelogListPanel)
    {
        super(new BorderLayout());
        this.createdByChangelogListPanel = createdByChangelogListPanel;
        this.entry = entry;
        this.panelService = panelService;
        this.plugin = plugin;

        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel headerBar = new JPanel(new GridLayout(1, 2, 4, 0));
        headerBar.setBorder(new EmptyBorder(4, 4, 4, 4));

        // If the ChangelogListPanel opened this changelog
        if(createdByChangelogListPanel){
            // Show a Back and Home button
            JButton backButton = new JButton();
            JButton homeButton = new JButton();

            backButton.setText("Back");
            backButton.setToolTipText("Return to the changelog list");
            backButton.addActionListener(e -> onBackButtonClicked());
            homeButton.setText("Home");
            homeButton.setToolTipText("Return to Goal Tracker home");
            homeButton.addActionListener(e -> onHomeButtonClicked());

            headerBar.add(backButton);
            headerBar.add(homeButton);
        }
        // If something else opened this changelog, like a new update
        else {
            // Show the Close and All Changelogs buttons
            JButton closeButton = new JButton();
            JButton seeAllButton = new JButton();

            closeButton.setText("Close");
            closeButton.setToolTipText("Close this changelog and return to Goal Tracker");
            closeButton.addActionListener(e -> onCloseButtonClicked());

            seeAllButton.setText("All Changelogs");
            seeAllButton.setToolTipText("Mark this update as seen and browse all changelog entries");
            seeAllButton.addActionListener(e -> onSeeAllButtonClicked());

            headerBar.add(closeButton);
            headerBar.add(seeAllButton);
        }

        JLabel titleLabel = new JLabel(isNewUpdate ? "New Update!" : "Goal Tracker Changelog");
        titleLabel.setFont(FontManager.getRunescapeBoldFont());
        titleLabel.setForeground(ColorScheme.BRAND_ORANGE);
        titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

        JLabel versionLabel = new JLabel("V" + entry.getVersion() + " Changes");
        versionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        versionLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

        JPanel titleSection = new JPanel();
        titleSection.setLayout(new BoxLayout(titleSection, BoxLayout.Y_AXIS));
        titleSection.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titleSection.setBorder(new EmptyBorder(8, 8, 4, 8));
        titleSection.add(titleLabel);
        titleSection.add(Box.createVerticalStrut(4));
        titleSection.add(versionLabel);

        JPanel topSection = new JPanel(new BorderLayout());
        topSection.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topSection.add(headerBar, BorderLayout.NORTH);
        topSection.add(titleSection, BorderLayout.CENTER);

        // JEditorPane as the scroll pane's DIRECT child - getScrollableTracksViewportWidth()
        // only takes effect when checked against the viewport's immediate view, so this
        // can't be nested inside another panel. This forces wrapping against the real
        // viewport width, no pixel-guessing needed.
        JEditorPane contentPane = new JEditorPane()
        {
            @Override
            public boolean getScrollableTracksViewportWidth()
            {
                return true;
            }
        };
        contentPane.setEditorKit(new ResponsiveImageEditorKit());
        contentPane.setEditable(false);
        contentPane.setFocusable(false);
        contentPane.setOpaque(false);
        contentPane.setBorder(new EmptyBorder(0, CONTENT_PADDING, CONTENT_PADDING, CONTENT_PADDING));
        contentPane.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        HTMLEditorKit htmlKit = (HTMLEditorKit) contentPane.getEditorKit();
        HTMLDocument htmlDocument = (HTMLDocument) htmlKit.createDefaultDocument();
        // A classpath root URL may be null for resources inside the plugin jar. Use a
        // known bundled image as the base so relative Markdown image paths resolve in
        // both exploded development builds and the packaged plugin.
        htmlDocument.setBase(ChangelogPanel.class.getResource("/add_child.png"));
        contentPane.setDocument(htmlDocument);
        contentPane.addHyperlinkListener(event ->
        {
            if (event.getEventType() == HyperlinkEvent.EventType.ACTIVATED && event.getURL() != null)
            {
                LinkBrowser.browse(event.getURL().toString());
            }
        });
        contentPane.setText(ChangelogMarkdownRenderer.toHtml(entry.getMarkdown(), entry.getVersion()));
        contentPane.setCaretPosition(0);

        JScrollPane scrollPane = new JScrollPane(contentPane);
        scrollPane.setBorder(BorderFactory.createEmptyBorder());
        scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        ScrollSpeedUtils.configure(scrollPane, plugin.getConfig());

        add(topSection, BorderLayout.NORTH);
        add(scrollPane, BorderLayout.CENTER);
    }

    private void onCloseButtonClicked() {
        plugin.getConfig().highestChangelogVersionSeen(entry.getVersion());
        panelService.showHome();
    }

    private void onSeeAllButtonClicked() {
        plugin.getConfig().highestChangelogVersionSeen(entry.getVersion());
        panelService.showChangelogListPanel();
    }

    private void onBackButtonClicked() {
        panelService.showChangelogListPanel();
    }

    private void onHomeButtonClicked() {
        panelService.showHome();
    }

    private static final class ResponsiveImageEditorKit extends HTMLEditorKit
    {
        private final ViewFactory viewFactory = new HTMLFactory()
        {
            @Override
            public View create(Element element)
            {
                Object name = element.getAttributes().getAttribute(StyleConstants.NameAttribute);
                if (name == HTML.Tag.IMG)
                {
                    return new ResponsiveImageView(element);
                }
                return super.create(element);
            }
        };

        @Override
        public ViewFactory getViewFactory()
        {
            return viewFactory;
        }
    }

    /** Scales oversized changelog images to the editor width while preserving aspect ratio. */
    private static final class ResponsiveImageView extends ImageView
    {
        private static final String WIDTH_METADATA_PREFIX = "[goaltracker-width=";
        private float allocatedWidth = -1;

        private ResponsiveImageView(Element element)
        {
            super(element);
        }

        @Override
        public String getAltText()
        {
            String altText = super.getAltText();
            if (altText != null && altText.startsWith(WIDTH_METADATA_PREFIX))
            {
                int end = altText.indexOf(']');
                if (end >= 0) return altText.substring(end + 1);
            }
            return altText;
        }

        @Override
        public float getPreferredSpan(int axis)
        {
            if (axis != View.X_AXIS && axis != View.Y_AXIS)
            {
                return super.getPreferredSpan(axis);
            }

            float imageWidth = super.getPreferredSpan(View.X_AXIS);
            float imageHeight = super.getPreferredSpan(View.Y_AXIS);
            if (imageWidth <= 0 || imageHeight <= 0)
            {
                return super.getPreferredSpan(axis);
            }

            float targetWidth = getRequestedWidth();
            if (targetWidth <= 0) targetWidth = imageWidth;

            Container container = getContainer();
            float availableWidth = 360;
            if (container != null && container.getWidth() > 0)
            {
                availableWidth = container.getWidth() - container.getInsets().left - container.getInsets().right
                        - CONTENT_PADDING;
            }

            targetWidth = Math.min(targetWidth, Math.max(1f, availableWidth));
            if (allocatedWidth > 0)
            {
                targetWidth = Math.min(targetWidth, allocatedWidth);
            }
            float scale = targetWidth / imageWidth;
            return axis == View.X_AXIS ? targetWidth : imageHeight * scale;
        }

        private float getRequestedWidth()
        {
            Object altAttribute = getElement().getAttributes().getAttribute(HTML.Attribute.ALT);
            if (altAttribute == null) return 0;

            String altText = altAttribute.toString();
            if (!altText.startsWith(WIDTH_METADATA_PREFIX)) return 0;
            int end = altText.indexOf(']');
            if (end < 0) return 0;
            try
            {
                return Integer.parseInt(altText.substring(WIDTH_METADATA_PREFIX.length(), end));
            }
            catch (NumberFormatException ignored)
            {
                return 0;
            }
        }

        @Override
        public void paint(Graphics graphics, Shape allocation)
        {
            Image image = getImage();
            if (image == null)
            {
                super.paint(graphics, allocation);
                return;
            }

            Rectangle bounds = allocation.getBounds();
            if (bounds.width > 0 && (allocatedWidth < 0 || Math.abs(allocatedWidth - bounds.width) > 1f))
            {
                allocatedWidth = bounds.width;
                preferenceChanged(null, true, true);
            }
            float preferredWidth = getPreferredSpan(View.X_AXIS);
            float preferredHeight = getPreferredSpan(View.Y_AXIS);
            if (preferredWidth <= 0 || preferredHeight <= 0)
            {
                super.paint(graphics, allocation);
                return;
            }
            float scale = Math.min(1f, Math.min(bounds.width / preferredWidth, bounds.height / preferredHeight));
            int width = Math.round(preferredWidth * scale);
            int height = Math.round(preferredHeight * scale);
            if (width <= 0 || height <= 0)
            {
                super.paint(graphics, allocation);
                return;
            }

            Graphics scaledGraphics = graphics.create(bounds.x, bounds.y, width, height);
            scaledGraphics.drawImage(image, 0, 0, width, height, null);
            scaledGraphics.dispose();
        }
    }
}

package com.darkforge317.goaltracker.ui;

import com.darkforge317.goaltracker.GoalTrackerPlugin;
import com.darkforge317.goaltracker.models.Goal;
import com.darkforge317.goaltracker.ui.components.ListItemPanel;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.event.PopupMenuEvent;
import javax.swing.event.PopupMenuListener;
import java.awt.*;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

import static com.darkforge317.goaltracker.utils.Constants.STATUS_TO_COLOR;

/**
 * UI component for rendering a Goal in a list.
 * Shows the title (editable), progress count, and a slim progress bar.
 * Also supports pinning, context menus, and refresh on goal status change.
 */
public final class GoalItemContent extends JPanel implements Refreshable
{
    private final JTextArea titleLabel = new JTextArea();
    private final JTextField titleEdit = new JTextField();
    private final JLabel progress = new JLabel();
    private final SlimBar progressBar = new SlimBar();
    private final JPanel titleStack = new JPanel(new CardLayout());

    private final Goal goal;

    private JPanel topRow;

    //private static final int PIN_STRIPE_W = 3; // px
    private static final Color PINNED_BG_COLOR = new Color(45, 45, 45); // darker gray background

    GoalItemContent(GoalTrackerPlugin plugin, Goal goal)
    {
        super(new BorderLayout());
        this.goal = goal;

        setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0)); // remove extra left/right padding so title can span edge-to-edge within the card body
        // Let the parent card body paint the background; avoid double fills
        setOpaque(false);
        setBackground(null);

        topRow = new JPanel(new BorderLayout());
        topRow.setOpaque(false);

        // Title label (display mode)
        titleLabel.setLineWrap(true);
        titleLabel.setWrapStyleWord(true);
        titleLabel.setEditable(false);
        titleLabel.setOpaque(false);
        titleLabel.setBorder(null);
        titleLabel.setFocusable(false);
        titleLabel.setFont(getFont());
        titleLabel.setMinimumSize(new Dimension(0, titleLabel.getPreferredSize().height));
        titleLabel.setMargin(new Insets(0, 0, 0, 0));

        // Title edit (edit mode)
        titleEdit.setBorder(null);
        titleEdit.setOpaque(false);
        titleEdit.setDragEnabled(true);

        // Constrain edit field so it never expands the card width
        titleEdit.setColumns(1); // keep preferred width minimal; BorderLayout will stretch it as needed
        int editH = titleEdit.getPreferredSize().height;
        titleEdit.setMinimumSize(new Dimension(0, editH));
        titleEdit.setPreferredSize(new Dimension(10, editH)); // tiny preferred width; parent determines real width
        // ESC cancels rename without saving
        InputMap im = titleEdit.getInputMap(JComponent.WHEN_FOCUSED);
        ActionMap am = titleEdit.getActionMap();
        im.put(KeyStroke.getKeyStroke(java.awt.event.KeyEvent.VK_ESCAPE, 0), "gt.cancelEdit");
        am.put("gt.cancelEdit", new AbstractAction() {
            @Override public void actionPerformed(java.awt.event.ActionEvent e) { exitEdit(false); }
        });

        titleStack.setOpaque(false);
        titleStack.add(titleLabel, "label");
        titleStack.add(titleEdit, "edit");
        topRow.add(titleStack, BorderLayout.CENTER);

        // Swap to edit only on LEFT double‑click (not on right‑click)
        titleLabel.addMouseListener(new MouseAdapter() {
            @Override public void mouseClicked(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 2) {
                    enterEdit();
                }
            }
        });
        // Commit edits on Enter and when focus is lost
        titleEdit.addActionListener(e -> exitEdit(true));
        titleEdit.addFocusListener(new java.awt.event.FocusAdapter() {
            @Override public void focusLost(java.awt.event.FocusEvent e) { exitEdit(true); }
        });

        // Place progress at the far right with a small left gap and a yellow border
        progress.setBorder(new javax.swing.border.EmptyBorder(0, 3, 0, 0));
        topRow.add(progress, BorderLayout.EAST);

        // Reserve fixed width for progress like 999/999 so it never clips
        int progW = getFontMetrics(progress.getFont()).stringWidth("999/999");
        Dimension progSize = new Dimension(progW, progress.getPreferredSize().height);
        progress.setPreferredSize(progSize);
        progress.setMinimumSize(progSize);
        add(topRow, BorderLayout.CENTER);

        // Slim custom progress bar under the title row
        progressBar.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0)); // gap above the bar
        progressBar.setPreferredSize(new Dimension(0, 6)); // 6px tall bar
        add(progressBar, BorderLayout.SOUTH);

        // Initialize visible text and colors immediately (before first refresh)
        {
            Color color = STATUS_TO_COLOR.get(goal.getStatus());
            updateTitleLabel();
            titleEdit.setCaretColor(color);
            progress.setText(goal.getComplete().size() + "/" + goal.getTasks().size());
            progress.setForeground(color);
        }

        topRow.addComponentListener(new ComponentAdapter() {
            @Override public void componentResized(ComponentEvent e) { updateTitleLabel(); }
        });

        plugin.getUiStatusManager().addRefresher(goal, this::refresh);

        // Ensure right-click on any child shows the parent ListItemPanel context menu
        MouseAdapter forwardPopup = new MouseAdapter()
        {
            private void maybeShow(MouseEvent e)
            {
                if (!e.isPopupTrigger())
                {
                    return;
                }
                Component src = (Component) e.getSource();
                JComponent listItem = (JComponent) SwingUtilities.getAncestorOfClass(ListItemPanel.class, src);
                if (listItem == null)
                {
                    listItem = (JComponent) SwingUtilities.getAncestorOfClass(ListItemPanel.class, GoalItemContent.this);
                }
                if (listItem != null && listItem.getComponentPopupMenu() != null)
                {
                    Point p = SwingUtilities.convertPoint(src, e.getPoint(), listItem);
                    JPopupMenu menu = listItem.getComponentPopupMenu();

                    JMenuItem rename = new JMenuItem("Rename");
                    ((JComponent) rename).putClientProperty("pinToggle", Boolean.TRUE); // reuse cleanup flag
                    rename.addActionListener(ev -> enterEdit());
                    menu.add(rename);

                    PopupMenuListener cleanup = new PopupMenuListener() {
                        @Override public void popupMenuWillBecomeVisible(PopupMenuEvent e) { }
                        @Override public void popupMenuCanceled(PopupMenuEvent e) { cleanup(menu, this); }
                        @Override public void popupMenuWillBecomeInvisible(PopupMenuEvent e) { cleanup(menu, this); }
                        private void cleanup(JPopupMenu m, PopupMenuListener self) {
                            // Remove only the components we added this time
                            java.util.List<Component> toRemove = new java.util.ArrayList<>();
                            for (Component c : m.getComponents()) {
                                if (c instanceof JComponent) {
                                    Object flag = ((JComponent) c).getClientProperty("pinToggle");
                                    if (Boolean.TRUE.equals(flag)) {
                                        toRemove.add(c);
                                    }
                                }
                            }
                            for (Component c : toRemove) {
                                m.remove(c);
                            }
                            m.removePopupMenuListener(self);
                        }
                    };
                    menu.addPopupMenuListener(cleanup);

                    menu.show(listItem, p.x, p.y);
                }
            }

            @Override public void mousePressed(MouseEvent e) { maybeShow(e); }
            @Override public void mouseReleased(MouseEvent e) { maybeShow(e); }
        };

        this.addMouseListener(forwardPopup);
        titleLabel.addMouseListener(forwardPopup);
        titleEdit.addMouseListener(forwardPopup);
        progress.addMouseListener(forwardPopup);
        progressBar.addMouseListener(forwardPopup);
        // Ensure item icon/text initialize on first render (e.g., on login)
        SwingUtilities.invokeLater(this::refresh);
    }

    @Override
    public void addNotify()
    {
        super.addNotify();
        // In case construction happened before UI was realized, refresh when shown
        SwingUtilities.invokeLater(this::refresh);
    }

    @Override
    public void refresh()
    {
        Color color = STATUS_TO_COLOR.get(goal.getStatus());

        updateTitleLabel();
        titleEdit.setCaretColor(color);

        progress.setText(
            goal.getComplete().size() + "/" + goal.getTasks().size());
        progress.setForeground(color);

        int total = goal.getTasks().size();
        int done = goal.getComplete().size();
        progressBar.setVisible(total > 0);
        progressBar.setProgress(done, total, color);
        SwingUtilities.invokeLater(this::updateTitleLabel);
    }
    private static class SlimBar extends JComponent {
        private int done = 0;
        private int total = 1;
        private Color fill = Color.GREEN;

        void setProgress(int done, int total, Color fill) {
            this.done = done;
            this.total = Math.max(1, total);
            this.fill = fill;
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            int w = getWidth();
            int h = getHeight();
            // track
            g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
            g2.fillRect(0, 0, w, h);
            // fill
            int barW = (int) ((done / (double) total) * w);
            g2.setColor(fill != null ? fill : Color.GREEN);
            g2.fillRect(0, 0, barW, h);
            g2.dispose();
        }
    }

    private void updateTitleLabel()
    {
        if (topRow == null) return;
        String full = goal.getDescription() != null ? goal.getDescription() : "";
        titleLabel.setText(full.isBlank() ? " " : full);
        titleLabel.setToolTipText(full.isEmpty() ? null : full);
    }

    private void enterEdit()
    {
        titleEdit.setText(goal.getDescription() != null ? goal.getDescription() : "");
        ((CardLayout) titleStack.getLayout()).show(titleStack, "edit");
        titleEdit.requestFocusInWindow();
        titleEdit.selectAll();
    }

    private void exitEdit(boolean save)
    {
        if (save) {
            String newText = titleEdit.getText();
            if (newText != null) {
                goal.setDescription(newText);
            }
        }
        ((CardLayout) titleStack.getLayout()).show(titleStack, "label");
        updateTitleLabel();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        if (goal != null && goal.isPinned())
        {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setColor(PINNED_BG_COLOR);
            g2.fillRect(0, 0, getWidth(), getHeight());
            g2.dispose();
        }
        super.paintComponent(g);
    }
}

