        prereqsButton.setToolTipText("Add prerequisite quests for this goal");
        prereqsButton.setEnabled(true);

        undoButton = new ActionBarButton("Undo", this::doUndo);
        redoButton = new ActionBarButton("Redo", this::doRedo);
        undoButton.setToolTipText("Undo the last task change");
        redoButton.setToolTipText("Redo the last undone task change");

        actionBar.left().add(prereqsButton);
        actionBar.left().add(undoButton);
        actionBar.left().add(redoButton);
        actionHistory.addListener(this::updateUndoRedoButtons);

        ActionBarButton importButton = new ActionBarButton("Import", () -> {
            String input = javax.swing.JOptionPane.showInputDialog(GoalPanel.this, "Paste goals JSON:");
            if (input == null) {
                return; // canceled
            }
            input = input.trim();
            if (input.isEmpty()) {
                return; // nothing to import
            }

            Object[] options = {"Overwrite", "Merge", "Cancel"};
            int choice = javax.swing.JOptionPane.showOptionDialog(
                    GoalPanel.this,
                    "Importing will change your current goals.\nDo you want to overwrite existing goals or merge with them?",
                    "Import Goals",
                    javax.swing.JOptionPane.YES_NO_CANCEL_OPTION,
                    javax.swing.JOptionPane.QUESTION_MESSAGE,
                    null,
                    options,
                    options[2]
            );

            if (choice == javax.swing.JOptionPane.YES_OPTION) {
                plugin.getGoalManager().importJson(input, true);   // Overwrite
            } else if (choice == javax.swing.JOptionPane.NO_OPTION) {
                plugin.getGoalManager().importJson(input, false);  // Merge
            } else {
                return; // canceled
            }

            // Refresh current view after import
            plugin.setValidateAll(true);
            plugin.getUiStatusManager().refresh(goal);
            refreshTaskList();
        });
        importButton.setToolTipText("Import goals from JSON text");
        actionBar.left().add(importButton);

        // Stack back row above the action bar in the header's NORTH
        JPanel headerTop = new JPanel();
        headerTop.setBackground(ColorScheme.DARK_GRAY_COLOR);
        headerTop.setLayout(new BoxLayout(headerTop, BoxLayout.Y_AXIS));
        headerTop.add(backRow);
        headerTop.add(actionBar);

        headerPanel.add(headerTop, BorderLayout.NORTH);

        updateUndoRedoButtons();

        descriptionInput = new EditableInput((value) -> {
            goal.setDescription(value);
            if (this.goalUpdatedListener != null) this.goalUpdatedListener.accept(goal);
        });
        headerPanel.add(descriptionInput, BorderLayout.CENTER);
        SwingUtilities.invokeLater(() -> installClipboardSupport(descriptionInput));
        descriptionInput.addContainerListener(new java.awt.event.ContainerAdapter()
        {
            @Override public void componentAdded(java.awt.event.ContainerEvent e)
            {
                SwingUtilities.invokeLater(() -> installClipboardSupport(descriptionInput));
            }
        });

        taskListPanel = new ListPanel<>(goal.getTasks(), (parent, task) -> {
            try {
                ListTaskPanel taskPanel = new ListTaskPanel(goal.getTasks(), task, parent, taskInteractionState);
                taskPanel.setActionHistory(actionHistory);
                TaskItemContent taskContent = new TaskItemContent(plugin, goal, task, taskInteractionState);
                taskContent.setActionHistory(actionHistory);
                taskContent.onAddChild(this::showAddChildDialog);
                taskPanel.add(taskContent);
                taskPanel.setTaskContent(taskContent);
                taskContent.refresh();
                taskPanel.setOpaque(true);
                taskPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
                taskPanel.setBorder(BorderFactory.createCompoundBorder(
                        BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.DARKER_GRAY_COLOR), // thinner divider
                        new EmptyBorder(2, 4, 2, 4)
                ));


                taskPanel.onParentChanged(e -> {
                    if (this.goalUpdatedListener != null) this.goalUpdatedListener.accept(goal);
                    plugin.getUiStatusManager().refresh(goal);
                    this.refresh();
                    updateUndoRedoButtons();
                });
                taskPanel.onPrerequisitesAdded(() -> {
                    if (!addingPrereqsBatch)
                    {
                        refreshAfterPrerequisitesAdded();
                    }
                });

                taskPanel.onRemovedWithIndex((removedTask, index) -> updateUndoRedoButtons());

                return taskPanel;
            } catch (Throwable t) {
                log.error("Failed to render task panel for task {}", task, t);
                // Render a minimal, visible error row instead of breaking the entire list
                ListTaskPanel fallback = new ListTaskPanel(goal.getTasks(), task, parent, taskInteractionState);
                JPanel error = new JPanel(new BorderLayout());
                error.setOpaque(true);
                error.setBackground(ColorScheme.DARK_GRAY_COLOR);
                JLabel msg = new JLabel("\u26A0\uFE0F Failed to render task; see log.");
                msg.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                msg.setBorder(new EmptyBorder(2, 4, 2, 4));
                error.add(msg, BorderLayout.CENTER);
                fallback.add(error);
                return fallback;
            }
        });
        ScrollSpeedUtils.configure(taskListPanel, plugin.getConfig());
        taskListPanel.setGap(0);
        taskListPanel.setPlaceholder("No tasks added yet");
        taskListPanel.onReordered((oldOrder, newOrder) -> {
            ActionHistory.Action action = new ActionHistory.Action()
            {
                private void apply(java.util.List<Task> order)
                {
                    goal.getTasks().clear();
                    goal.getTasks().addAll(order);
                    TaskHierarchyUtils.normalizeIndentLevels(goal.getTasks());
                    plugin.getUiStatusManager().refresh(goal);
                }

                @Override public void undo() { apply(oldOrder); }
                @Override public void redo() { apply(newOrder); }
            };
            actionHistory.push(action);
            updateUndoRedoButtons();
        });
        taskListPanel.setRowVisibilityFilter(task -> !TaskHierarchyUtils.hasCollapsedAncestor(goal.getTasks(), task));
        taskListPanel.setHiddenRowAnchor(task -> TaskHierarchyUtils.getVisibleCollapsedAncestor(goal.getTasks(), task));
        taskListPanel.setDragGroupProvider(task -> TaskHierarchyUtils.getSubtree(goal.getTasks(), task));
        taskListPanel.setDragBoundsProvider((visibleItems, movedTask) ->
                TaskHierarchyUtils.getValidInsertionSlots(goal.getTasks(), visibleItems, movedTask));
        taskListPanel.setReorderValidator((order, movedTask) ->
                !TaskHierarchyUtils.hasCollapsedAncestor(order, movedTask));
        taskListPanel.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_NEVER);
        taskListPanel.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        taskListPanel.setWheelScrollingEnabled(false);

        // Use a custom layout panel wrapper that allows horizontal overflow
        JPanel scrollableContainer = new JPanel(new BorderLayout()) {
            @Override
            public Dimension getPreferredSize() {
                // Let the container stretch horizontally based on its actual padded contents
                return taskListPanel.getPreferredSize();
            }
        };
        scrollableContainer.add(taskListPanel, BorderLayout.CENTER);

        JScrollPane taskListScrollPane = new JScrollPane(scrollableContainer) {
            @Override
            public Dimension getPreferredSize() {
                Dimension preferred = super.getPreferredSize();
                Container parent = getParent();
                if (parent != null) {
                    // Frame the visible box precisely to the width of the sidebar
                    preferred.width = parent.getWidth();
                }
                return preferred;
            }
        };

        // Keep vertical scrolling active; allow horizontal layout expansion
        // This allows a larger amount of indentation levels without cramming
        taskListScrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        taskListScrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);

        // Remove the thick default border frames to preserve the native RuneLite styling
        taskListScrollPane.setBorder(BorderFactory.createEmptyBorder());
        taskListScrollPane.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);

        taskListScrollPane.setBorder(BorderFactory.createEmptyBorder());
        taskListScrollPane.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);

        // setWheelScrollingEnabled(false) above stops the inner pane from acting on wheel
        // events, but Swing still delivers them to it first since it has a registered
        // listener - explicitly forward to the outer pane instead of leaving them stranded.
        taskListPanel.addMouseWheelListener(e ->
                taskListScrollPane.dispatchEvent(
                        (MouseWheelEvent) SwingUtilities.convertMouseEvent(taskListPanel, e, taskListScrollPane)
                )
        );

        ScrollSpeedUtils.configure(taskListScrollPane, plugin.getConfig());

        // Mount the scroll window to the center
        add(taskListScrollPane, BorderLayout.CENTER);

        NewTaskPanel newTaskPanel = new NewTaskPanel(plugin, goal);
        newTaskPanel.onTaskAdded(this::updateFromNewTask);
        add(newTaskPanel, BorderLayout.SOUTH);

        // Global ESC to go back
        getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT)
                .put(KeyStroke.getKeyStroke(java.awt.event.KeyEvent.VK_ESCAPE, 0), "gt.back");
        getActionMap().put("gt.back", new javax.swing.AbstractAction() {
            @Override public void actionPerformed(java.awt.event.ActionEvent e) { closeListener.run(); }
        });
    }

    public void updateFromNewTask(Task task)
    {
        taskListPanel.tryBuildList();
        taskListPanel.refresh();
        plugin.setValidateAll(true);
        plugin.getUiStatusManager().refresh(goal);
        revalidate();
        repaint();

        if (Objects.nonNull(this.taskAddedListener)) this.taskAddedListener.accept(task);
        if (Objects.nonNull(this.taskUpdatedListener)) this.taskUpdatedListener.accept(task);
    }

    private void showAddChildDialog(Task parentTask)
    {
        if (parentTask.getIndentLevel() >= Task.MAX_INDENT_LEVEL)
        {
            JOptionPane.showMessageDialog(this,
                    "This task is already at the maximum nesting depth.",
                    "Cannot add child",
                    JOptionPane.WARNING_MESSAGE);
            return;
        }

        if (addChildDialog != null && addChildDialog.isDisplayable())
        {
            addChildDialog.toFront();
            return;
        }

        Window owner = SwingUtilities.getWindowAncestor(this);
        JDialog dialog = new JDialog(owner, "Add child task for " + parentTask, Dialog.ModalityType.MODELESS);
        addChildDialog = dialog;
        dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        dialog.setLayout(new BorderLayout(0, 8));

        NewTaskPanel childTaskPanel = new NewTaskPanel(plugin, goal);
        childTaskPanel.onTaskAdded(child -> {
            if (!goal.getTasks().contains(parentTask))
            {
                goal.getTasks().remove(child);
                if (goalUpdatedListener != null) goalUpdatedListener.accept(goal);
                plugin.getUiStatusManager().refresh(goal);
                refreshTaskList();
                JOptionPane.showMessageDialog(this,
                    "The parent task was removed before the child could be added.",
                    "Cannot add child",
                    JOptionPane.WARNING_MESSAGE);
                childTaskPanel.closeItemSearch();
                dialog.dispose();
                return;
            }
            addChildTask(parentTask, child);
            childTaskPanel.closeItemSearch();
            dialog.dispose();
        });
        childTaskPanel.expandMoreOptions();
        Dimension childPanelSize = childTaskPanel.getPreferredSize();
        childTaskPanel.setPreferredSize(new Dimension(320, childPanelSize.height));
        JScrollPane childTaskScrollPane = new JScrollPane(childTaskPanel,
                ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
                ScrollPaneConstants.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        childTaskScrollPane.setBorder(BorderFactory.createEmptyBorder());
        ScrollSpeedUtils.configure(childTaskScrollPane, plugin.getConfig());
        childTaskScrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        childTaskScrollPane.setPreferredSize(new Dimension(320, childPanelSize.height));
        dialog.add(childTaskScrollPane, BorderLayout.CENTER);

        JButton cancelButton = new JButton("Cancel");
        cancelButton.addActionListener(e -> {
            childTaskPanel.closeItemSearch();
            dialog.dispose();
        });
        JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        buttonPanel.add(cancelButton);
        dialog.add(buttonPanel, BorderLayout.SOUTH);
        dialog.addWindowListener(new java.awt.event.WindowAdapter()
        {
            @Override public void windowClosing(java.awt.event.WindowEvent event)
            {
                childTaskPanel.closeItemSearch();
            }

            @Override public void windowClosed(java.awt.event.WindowEvent event)
            {
                if (addChildDialog == dialog)
                {
                    addChildDialog = null;
                }
            }
        });

        dialog.pack();
        dialog.setLocationRelativeTo(this);
        dialog.setVisible(true);
    }

    private void addChildTask(Task parentTask, Task childTask)
    {
        ReorderableList<Task> tasks = goal.getTasks();
        tasks.remove(childTask); // TaskInput appends before notifying its listener.
        TaskHierarchyUtils.ensureTaskIds(tasks);
        TaskHierarchyUtils.ensureTaskIds(java.util.Collections.singletonList(childTask));

        int insertionIndex = tasks.indexOf(parentTask) + 1;
        for (Task descendant : TaskHierarchyUtils.getDescendants(tasks, parentTask))
        {
            insertionIndex = Math.max(insertionIndex, tasks.indexOf(descendant) + 1);
        }
        final int childIndex = insertionIndex;
        final boolean parentWasCollapsed = parentTask.isCollapsed();

        ActionHistory.Action action = new ActionHistory.Action()
        {
            @Override public void undo()
            {
                tasks.remove(childTask);
                parentTask.setCollapsed(parentWasCollapsed);
                TaskHierarchyUtils.normalizeIndentLevels(tasks);
                if (goalUpdatedListener != null) goalUpdatedListener.accept(goal);
                plugin.getUiStatusManager().refresh(goal);
            }

            @Override public void redo()
            {
                childTask.setParentTaskId(parentTask.getTaskId());
                tasks.add(Math.max(0, Math.min(childIndex, tasks.size())), childTask);
                parentTask.setCollapsed(false);
                TaskHierarchyUtils.normalizeIndentLevels(tasks);
                if (goalUpdatedListener != null) goalUpdatedListener.accept(goal);
                plugin.getUiStatusManager().refresh(goal);
            }
        };

        action.redo();
        actionHistory.push(action);
        updateUndoRedoButtons();
        if (this.goalUpdatedListener != null) this.goalUpdatedListener.accept(goal);
        updateFromNewTask(childTask);
    }

    public void refreshTaskList()
    {
        taskListPanel.tryBuildList();
        taskListPanel.refresh();
        plugin.getUiStatusManager().refresh(goal);
        revalidate();
        repaint();
    }

    @Override
    public void refresh()
    {
        descriptionInput.setValue(goal.getDescription());
        taskListPanel.refresh();
    }

