    // Custom Trash Cursor Assets
    private static final Cursor DEFAULT_PANEL_CURSOR = Cursor.getPredefinedCursor(Cursor.DEFAULT_CURSOR);
    private static final Cursor TRASH_CURSOR;
    private static final int TRASH_ICON_SIZE = 20;

    static {
        Cursor tempCursor;
        try {
            BufferedImage trashImg = net.runelite.client.util.ImageUtil.loadImageResource(TaskItemContent.class, "/trash.png");

            // The OS enforces its own native cursor canvas size (often 32x32 on Windows)
            // and will stretch whatever we pass in to fill it - so instead of shrinking
            // the whole image, we draw a small icon inside a canvas of the OS's actual size.
            Dimension nativeSize = java.awt.Toolkit.getDefaultToolkit()
                    .getBestCursorSize(TRASH_ICON_SIZE, TRASH_ICON_SIZE);
            int canvasW = Math.max(nativeSize.width, TRASH_ICON_SIZE);
            int canvasH = Math.max(nativeSize.height, TRASH_ICON_SIZE);

            BufferedImage canvas = new BufferedImage(canvasW, canvasH, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g2d = canvas.createGraphics();
            g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            // Draw the icon at its intended small size, anchored top-left so the hotspot stays accurate
            g2d.drawImage(trashImg, 0, 0, TRASH_ICON_SIZE, TRASH_ICON_SIZE, null);
            g2d.dispose();

            Point hotspot = new Point(0, 0);
            tempCursor = java.awt.Toolkit.getDefaultToolkit().createCustomCursor(canvas, hotspot, "TrashCursor");
        } catch (Exception e) {
            tempCursor = Cursor.getPredefinedCursor(Cursor.CROSSHAIR_CURSOR);
        }
        TRASH_CURSOR = tempCursor;
    }

    private static final int ARROW_SIZE = 10; // px - tweak overall arrow size here
    private static final int ADD_CHILD_ICON_SIZE = 11;
    private static final ImageIcon COLLAPSED_ARROW_ICON;
    private static final ImageIcon EXPANDED_ARROW_ICON;
    private static final ImageIcon BLANK_ARROW_ICON;

    static {
        ImageIcon collapsedIcon = null;
        ImageIcon expandedIcon = null;
        try {
            BufferedImage collapsedSrc = net.runelite.client.util.ImageUtil.loadImageResource(TaskItemContent.class, "/collapsed_task.png");
            BufferedImage expandedSrc = net.runelite.client.util.ImageUtil.loadImageResource(TaskItemContent.class, "/expanded_task.png");
            collapsedIcon = new ImageIcon(resizeImage(collapsedSrc, ARROW_SIZE, ARROW_SIZE));
            expandedIcon = new ImageIcon(resizeImage(expandedSrc, ARROW_SIZE, ARROW_SIZE));
        } catch (Exception e) {
            // Leave both null; refresh() falls back to a blank icon either way
        }
        COLLAPSED_ARROW_ICON = collapsedIcon;
        EXPANDED_ARROW_ICON = expandedIcon;
        BLANK_ARROW_ICON = new ImageIcon(new BufferedImage(ARROW_SIZE, ARROW_SIZE, BufferedImage.TYPE_INT_ARGB));
    }

    private static BufferedImage resizeImage(BufferedImage src, int w, int h) {
        BufferedImage resized = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = resized.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2d.drawImage(src, 0, 0, w, h, null);
        g2d.dispose();
        return resized;
    }

