        BufferedImage addChildImage = net.runelite.client.util.ImageUtil.loadImageResource(TaskItemContent.class, "/add_child.png");
        addChildButton.setIcon(new ImageIcon(resizeImage(addChildImage, ADD_CHILD_ICON_SIZE, ADD_CHILD_ICON_SIZE)));
        addChildButton.setPreferredSize(new Dimension(ADD_CHILD_ICON_SIZE + 8, 24));
        addChildButton.setBorder(new EmptyBorder(0, 4, 0, 4));
        addChildButton.onClick(e -> {
            if (interactionState.getMode() != TaskInteractionState.Mode.NORMAL) return;
            if (addChildListener != null) addChildListener.accept(task);
        });

        JPanel titleRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        titleRow.setOpaque(false);
        titleRow.add(titleStack);
        titleRow.add(addChildButton);
        add(titleRow, BorderLayout.CENTER);

        iconWrapper = new JPanel(new BorderLayout());
        iconWrapper.setBorder(new EmptyBorder(0, 0, 0, 0));
        iconWrapper.add(iconLabel, BorderLayout.NORTH);

        collapseArrow.setBorder(new EmptyBorder(0, 0, 0, 2));
        collapseArrow.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                if (interactionState.getMode() != TaskInteractionState.Mode.NORMAL
                        || !TaskHierarchyUtils.hasChildren(goal.getTasks(), task)) return;
                task.setCollapsed(!task.isCollapsed());
                Container ancestor = SwingUtilities.getAncestorOfClass(ListPanel.class, TaskItemContent.this);
                if (ancestor instanceof ListPanel) {
                    ((ListPanel<?>) ancestor).tryBuildList();
                    ((ListPanel<?>) ancestor).refresh();
                }
            }
        });

        // Pin the arrow to the top of its own slot, same as iconLabel above, so it
        // aligns with the icon instead of stretching/centering in the full row height
        JPanel arrowWrapper = new JPanel(new BorderLayout());
        arrowWrapper.add(collapseArrow, BorderLayout.NORTH);

        iconRow = new JPanel(new BorderLayout());
        iconRow.setBorder(new EmptyBorder(4, 0, 0, 4));
        iconRow.add(arrowWrapper, BorderLayout.WEST);
        iconRow.add(iconWrapper, BorderLayout.CENTER);
        add(iconRow, BorderLayout.WEST);

        plugin.getUiStatusManager().addRefresher(task, this::refresh);

//        this.addComponentListener(new ComponentAdapter() {
//            @Override public void componentResized(ComponentEvent e) { updateTitleLabel(); }
//        });

        titleEditable = (task instanceof ManualTask);
        if (titleEditable) {
            titleLabel.addMouseListener(new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e) {
                    if (interactionState.getMode() == TaskInteractionState.Mode.NORMAL) enterEdit();
                }
            });
            titleEdit.addActionListener(e -> exitEdit(true));
            titleEdit.addFocusListener(new FocusAdapter() {
                @Override public void focusLost(FocusEvent e) { exitEdit(true); }
            });
        }

        this.addAncestorListener(new AncestorListener() {
            @Override
            public void ancestorAdded(AncestorEvent event) {
                plugin.getKeyInputService().addListener(shiftStateListener);
                interactionState.addListener(interactionStateListener);
                onInteractionStateChanged();
            }

            @Override
            public void ancestorRemoved(AncestorEvent event) {
                plugin.getKeyInputService().removeListener(shiftStateListener);
                interactionState.removeListener(interactionStateListener);
            }

            @Override
            public void ancestorMoved(AncestorEvent event) {}
        });

        // Right-click to toggle completion with ActionHistory
        MouseAdapter contextMenuListener = new MouseAdapter()
        {
            private void showMenuIfNeeded(MouseEvent e)
            {
                if (interactionState.getMode() == TaskInteractionState.Mode.SET_PARENT) return;
                if (!(e.isPopupTrigger() || SwingUtilities.isRightMouseButton(e)))
                {
                    return;
                }
                // Prefer the parent ListItemPanel context menu (move up/down/remove, etc.)
                Component src = (Component) e.getSource();
                JComponent listItem = (JComponent) SwingUtilities.getAncestorOfClass(ListItemPanel.class, src);
                if (listItem != null && listItem.getComponentPopupMenu() != null)
                {
                    Point p = SwingUtilities.convertPoint(src, e.getPoint(), listItem);
                    listItem.getComponentPopupMenu().show(listItem, p.x, p.y);
                    return;
                }

                // Fallback: show simple toggle menu if no parent popup menu is available
                boolean currentlyComplete = task.getStatus() == Status.COMPLETED;
                String label = currentlyComplete ? "Mark as Incomplete" : "Mark as Completed";

                JPopupMenu menu = new JPopupMenu();
                JMenuItem toggle = new JMenuItem(label);
                toggle.addActionListener(a -> {
                    ToggleCompleteAction act = new ToggleCompleteAction(task, currentlyComplete, !currentlyComplete);
                    act.redo();
                    if (actionHistory != null)
                    {
                        actionHistory.push(act);
                    }
                    plugin.getUiStatusManager().refresh(goal);
                });
                menu.add(toggle);
                Component invoker = (Component) e.getSource();
                menu.show(invoker, e.getX(), e.getY());
            }

            @Override public void mousePressed(MouseEvent e) { showMenuIfNeeded(e); }
            @Override public void mouseReleased(MouseEvent e) { showMenuIfNeeded(e); }
        };

        // Attach listener to multiple components to make right-click reliable across platforms
        this.addMouseListener(contextMenuListener);
        titleStack.addMouseListener(contextMenuListener);
        titleLabel.addMouseListener(contextMenuListener);
        titleEdit.addMouseListener(contextMenuListener);
        iconLabel.addMouseListener(contextMenuListener);

        // Ensure cursor styles adapt on hover and on any real mouse movement while Shift is held.
        // (No global KeyboardFocusManager hook - RuneLite plugin hub disallows JVM-wide key
        // listeners, so Shift state is only checked from the MouseEvent itself.)
        MouseAdapter rowHoverCursorAdapter = new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                syncShiftFromMouseEvent(e);
                updateCursorForModifiers(e.getModifiersEx());
            }

            @Override
            public void mouseMoved(MouseEvent e) {
                syncShiftFromMouseEvent(e);
                updateCursorForModifiers(e.getModifiersEx());
            }

            @Override
            public void mousePressed(MouseEvent e) {
                syncShiftFromMouseEvent(e);
                updateCursorForModifiers(e.getModifiersEx());
            }

            @Override
            public void mouseExited(MouseEvent e) {
                if (parentSelectionMode) return;
                PointerInfo pi = MouseInfo.getPointerInfo();
                if (pi != null) {
                    Point mousePos = pi.getLocation();
                    SwingUtilities.convertPointFromScreen(mousePos, TaskItemContent.this);

                    if (!TaskItemContent.this.contains(mousePos)) {
                        updateCursorForModifiers(0);
                    }
                } else {
                    updateCursorForModifiers(0);
                }
            }
        };

        this.addMouseListener(rowHoverCursorAdapter);
        this.addMouseMotionListener(rowHoverCursorAdapter);
        titleStack.addMouseListener(rowHoverCursorAdapter);
        titleStack.addMouseMotionListener(rowHoverCursorAdapter);
        titleLabel.addMouseListener(rowHoverCursorAdapter);
        titleLabel.addMouseMotionListener(rowHoverCursorAdapter);
        titleEdit.addMouseListener(rowHoverCursorAdapter);
        titleEdit.addMouseMotionListener(rowHoverCursorAdapter);
        iconLabel.addMouseListener(rowHoverCursorAdapter);
        iconLabel.addMouseMotionListener(rowHoverCursorAdapter);
        addChildButton.addMouseListener(rowHoverCursorAdapter);
        addChildButton.addMouseMotionListener(rowHoverCursorAdapter);
        collapseArrow.addMouseListener(rowHoverCursorAdapter);
        collapseArrow.addMouseMotionListener(rowHoverCursorAdapter);
        if (iconWrapper != null) {
            iconWrapper.addMouseListener(rowHoverCursorAdapter);
            iconWrapper.addMouseMotionListener(rowHoverCursorAdapter);
        }
    }

    public boolean canEditTarget()
    {
        return TaskTargetEditor.supports(task);
    }

    public void editTarget()
    {
        TaskTargetEditor.open(this, plugin, goal, task);
    }

    private void onShiftStateChanged()
    {
        interactionState.setShiftDown(plugin.getKeyInputService().isShiftDown());
    }

    private void syncShiftFromMouseEvent(MouseEvent event)
    {
        interactionState.setShiftDown((event.getModifiersEx() & InputEvent.SHIFT_DOWN_MASK) != 0);
    }

    private void onInteractionStateChanged()
    {
        setInteractionMode(interactionState.getMode());
        if (parentSelectionMode) return;
        PointerInfo pi = MouseInfo.getPointerInfo();
        if (pi == null) return;

        Point mousePos = pi.getLocation();
        SwingUtilities.convertPointFromScreen(mousePos, this);
        if (!this.contains(mousePos)) return; // mouse isn't over this row, nothing to refresh

        updateCursorForModifiers(0);

        Point labelPos = pi.getLocation();
        SwingUtilities.convertPointFromScreen(labelPos, titleLabel);
        if (titleLabel.contains(labelPos)) {
            int modifiers = interactionState.getMode() == TaskInteractionState.Mode.SHIFT_DELETE
                    ? InputEvent.SHIFT_DOWN_MASK : 0;
            MouseEvent moveEvent = new MouseEvent(titleLabel, MouseEvent.MOUSE_MOVED,
                    System.currentTimeMillis(), modifiers, labelPos.x, labelPos.y, 0, false);
            ToolTipManager.sharedInstance().mouseMoved(moveEvent);
        }
    }

    private void updateCursorForModifiers(int modifiersEx) {
        if (parentSelectionMode) return;
        boolean shiftDelete = interactionState.getMode() == TaskInteractionState.Mode.SHIFT_DELETE;
        updateAllChildCursors(shiftDelete ? TRASH_CURSOR : DEFAULT_PANEL_CURSOR);
        if (!shiftDelete && interactionState.getMode() == TaskInteractionState.Mode.NORMAL) {
            addChildButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        }
        if (!shiftDelete && TaskHierarchyUtils.hasChildren(goal.getTasks(), task)
                && COLLAPSED_ARROW_ICON != null) {
            collapseArrow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        }
    }

    private void updateAllChildCursors(Cursor cursor) {
        this.setCursor(cursor);
        titleStack.setCursor(cursor);
        titleLabel.setCursor(cursor);
        titleEdit.setCursor(cursor);
        iconLabel.setCursor(cursor);
        collapseArrow.setCursor(cursor);
        addChildButton.setCursor(cursor);
        if (iconWrapper != null) {
            iconWrapper.setCursor(cursor);
        }
    }

    @Override
    public void refresh()
    {
        titleLabel.setForeground(STATUS_TO_COLOR.get(task.getStatus()));
        updateTitleLabel();

        int level = Math.max(0, task.getIndentLevel());
        // Indent level scales linearly: 0 = 0px, 1 = 12px, 2 = 24px, 3 = 36px, etc.
        int indent = level * INDENT_PER_LEVEL;

        iconService.updateIcon(task, iconLabel);
        // Apply indent to the row instead of the label to avoid double padding
        iconLabel.setBorder(new EmptyBorder(0, 0, 0, 0));
        iconRow.setBorder(new EmptyBorder(4, indent, 0, 4));

        boolean hasChildren = TaskHierarchyUtils.hasChildren(goal.getTasks(), task);
        if (hasChildren && COLLAPSED_ARROW_ICON != null) {
            collapseArrow.setIcon(task.isCollapsed() ? COLLAPSED_ARROW_ICON : EXPANDED_ARROW_ICON);
            collapseArrow.setCursor(interactionState.getMode() == TaskInteractionState.Mode.SHIFT_DELETE
                    ? TRASH_CURSOR : Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        } else {
            collapseArrow.setIcon(BLANK_ARROW_ICON);
            collapseArrow.setCursor(interactionState.getMode() == TaskInteractionState.Mode.SHIFT_DELETE
                    ? TRASH_CURSOR : DEFAULT_PANEL_CURSOR);
        }

        revalidate();
    }

    public void onAddChild(Consumer<Task> listener)
    {
        this.addChildListener = listener;
    }

    public Component getAddChildButton()
    {
        return addChildButton;
    }

    private void setInteractionMode(TaskInteractionState.Mode mode)
    {
        parentSelectionMode = mode == TaskInteractionState.Mode.SET_PARENT;
        boolean normalMode = mode == TaskInteractionState.Mode.NORMAL;
        addChildButton.setHoverEffectsEnabled(normalMode);
        addChildButton.setToolTipText(normalMode ? "Add child task" : null);
    }

    @Override
    public void setBackground(Color bg)
    {
        super.setBackground(bg);
        for (Component component : getComponents()) {
            component.setBackground(bg);
        }
    }

    private void updateTitleLabel()
    {
        String full = task.toString();
        if (full == null) full = "";

        titleLabel.setToolTipText(full.isEmpty() ? null : full);

        // Always set the full string without truncating it
        titleLabel.setText(full);

        // Get Swing to calculate the true physical width of this full text string
        FontMetrics fm = titleLabel.getFontMetrics(titleLabel.getFont());
        int naturalWidth = fm.stringWidth(full);

        // Apply the true width to the label so parent containers expand horizontally
        titleLabel.setPreferredSize(new Dimension(naturalWidth, 24));
        titleStack.revalidate();
    }

    private void enterEdit()
    {
        if (!titleEditable) return;
        titleEdit.setText(task.toString());
        ((CardLayout) titleStack.getLayout()).show(titleStack, "edit");
        titleEdit.requestFocusInWindow();
        titleEdit.selectAll();
    }

    private void exitEdit(boolean save)
    {
        if (!titleEditable) { ((CardLayout) titleStack.getLayout()).show(titleStack, "label"); return; }
        if (save) {
            String newText = titleEdit.getText();
            if (newText != null && task instanceof ManualTask) {
                ((ManualTask) task).setDescription(newText);
            }
        }
        ((CardLayout) titleStack.getLayout()).show(titleStack, "label");
        updateTitleLabel();
        plugin.getUiStatusManager().refresh(goal);
    }

    /**
     * Try to invoke the same context menu action as right-click -> "Add prerequisites".
     * @return true if the action was found and invoked, false otherwise
     */
    public boolean addPrereqsFromContext()
    {
        JComponent listItem = (JComponent) SwingUtilities.getAncestorOfClass(ListItemPanel.class, this);
        if (listItem == null || listItem.getComponentPopupMenu() == null)
        {
            return false;
        }

        JPopupMenu menu = listItem.getComponentPopupMenu();
        // Accept several label variants (case-insensitive)
        String[] targets = new String[] {
                "add prerequisites", "add pre-reqs", "add prereqs", "prerequisites"
        };

        return clickMenuItemByLabels(menu.getSubElements(), targets);
    }

    // Recursively search menu/submenus for a matching label and click it.
    private static boolean clickMenuItemByLabels(MenuElement[] items, String[] needles)
    {
        for (MenuElement me : items)
        {
            if (me instanceof JMenuItem)
            {
                JMenuItem it = (JMenuItem) me;
                String txt = it.getText();
                if (txt != null)
                {
                    String lower = txt.toLowerCase(Locale.ROOT).trim();
                    for (String needle : needles)
                    {
                        if (lower.contains(needle))
                        {
                            it.doClick();
                            return true;
                        }
                    }
                }
            }
            // Recurse into submenus and containers
            MenuElement[] children = me.getSubElements();
            if (children != null && children.length > 0 && clickMenuItemByLabels(children, needles))
            {
                return true;
            }
        }
        return false;
    }
}

package com.darkforge317.goaltracker.ui;

import com.darkforge317.goaltracker.GoalTrackerPlugin;
import com.darkforge317.goaltracker.models.Goal;
import com.darkforge317.goaltracker.models.enums.Status;
import com.darkforge317.goaltracker.models.task.*;
import net.runelite.api.Skill;
import com.darkforge317.goaltracker.ui.components.SkillTargetFields;
import com.darkforge317.goaltracker.ui.inputs.QuestPointsTaskInput;

import javax.swing.*;
import java.awt.*;
import java.util.Locale;

/** Edits targets in place so their position, children and collapsed state survive. */
final class TaskTargetEditor
{
    static boolean supports(Task task)
    {
        return task instanceof SkillLevelTask || task instanceof SkillXpTask || task instanceof ItemTask
            || task instanceof CombatLevelTask || task instanceof QuestPointsTask;
    }

    static int parseTarget(String value, int maximum)
    {
        String text = value.trim().toLowerCase(Locale.ROOT);
        long multiplier = 1;
        if (text.endsWith("k") || text.endsWith("m"))
        {
            multiplier = text.endsWith("k") ? 1000 : 1000000;
            text = text.substring(0, text.length() - 1);
        }
        if (!text.matches("[0-9]+")) throw new IllegalArgumentException();
        long result = Math.multiplyExact(Long.parseLong(text), multiplier);
        if (result < 1 || result > maximum) throw new IllegalArgumentException();
        return (int) result;
    }

    /** Preserve list placement and hierarchy when switching between level and exact XP targets. */
    static Task retargetSkill(Task task, boolean level, int value)
    {
        Skill skill = task instanceof SkillLevelTask ? ((SkillLevelTask) task).getSkill()
            : ((SkillXpTask) task).getSkill();
        Task result;
        if (level)
        {
            SkillLevelTask target = task instanceof SkillLevelTask ? (SkillLevelTask) task
                : SkillLevelTask.builder().build();
            target.setSkill(skill);
            target.setTargetSkillLevel(value);
            target.setStatus(target.hasReachedTargetLevel() ? Status.COMPLETED : Status.NOT_STARTED);
            result = target;
        }
        else
        {
            SkillXpTask target = task instanceof SkillXpTask ? (SkillXpTask) task
                : SkillXpTask.builder().build();
            target.setSkill(skill);
            target.setTargetSkillXp(value);
            target.setStatus(target.hasReachedTargetXp() ? Status.COMPLETED : Status.NOT_STARTED);
            result = target;
        }
        result.setTaskId(task.getTaskId());
        result.setParentTaskId(task.getParentTaskId());
        result.setIndentLevel(task.getIndentLevel());
        result.setCollapsed(task.isCollapsed());
        return result;
    }

    static JSpinner createQuantitySpinner(int value)
    {
        JSpinner spinner = new JSpinner(new SpinnerNumberModel(Math.max(1, value), 1, Integer.MAX_VALUE, 1));
        JSpinner.NumberEditor editor = new JSpinner.NumberEditor(spinner, "0");
        JFormattedTextField field = editor.getTextField();
        field.setColumns(12);
        field.setFormatterFactory(new javax.swing.text.DefaultFormatterFactory(new JFormattedTextField.AbstractFormatter() {
            @Override public Object stringToValue(String text) throws java.text.ParseException
            {
                try { return parseTarget(text, Integer.MAX_VALUE); }
                catch (IllegalArgumentException | ArithmeticException ex)
                {
                    throw new java.text.ParseException("Enter a positive whole quantity (k/m allowed).", 0);
                }
            }
            @Override public String valueToString(Object number)
            {
                return number == null ? "" : number.toString();
            }
        }));
        field.getAccessibleContext().setAccessibleName("Target quantity");
        field.setToolTipText("Quantity 1–2147483647; accepts k/m suffixes");
        spinner.setEditor(editor);
        return spinner;
    }

    static JSpinner createCombatLevelSpinner(int value)
    {
        return createCombatLevelSpinner((double) value);
    }

    static JSpinner createCombatLevelSpinner(double value)
    {
        double boundedValue = Math.max(3, Math.min(126, value));
        SpinnerNumberModel model = new SpinnerNumberModel(boundedValue, 3.0, 126.0, 0.25)
        {
            @Override public void setValue(Object value)
            {
                if (!(value instanceof Number))
                {
                    throw new IllegalArgumentException("Combat level must be between 3 and 126.");
                }
                Number number = (Number) value;
                double target = number.doubleValue();
                if (!Double.isFinite(target) || target < 3 || target > 126
                    || Math.abs(target * 100 - Math.rint(target * 100)) > 0.000001)
                {
                    throw new IllegalArgumentException("Combat level must be between 3 and 126, with at most two decimal places.");
                }
                super.setValue(target);
            }
        };
        JSpinner spinner = new JSpinner(model);
        JSpinner.NumberEditor editor = new JSpinner.NumberEditor(spinner, "0.00");
        editor.getTextField().setColumns(5);
        editor.getTextField().setHorizontalAlignment(SwingConstants.LEFT);
        editor.getTextField().getAccessibleContext().setAccessibleName("Target combat level");
        editor.getTextField().setToolTipText("Combat level 3–126; up to two decimal places");
        spinner.setEditor(editor);
        return spinner;
    }

    static void open(Component parent, GoalTrackerPlugin plugin, Goal goal, Task task)
    {
        if (!supports(task)) return;
        JDialog dialog = new JDialog(SwingUtilities.getWindowAncestor(parent), "Edit goal", Dialog.ModalityType.MODELESS);
        JPanel fields = new JPanel(new BorderLayout(0, 12));
        fields.setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        boolean level = task instanceof SkillLevelTask;
        ItemTask item = task instanceof ItemTask ? (ItemTask) task : null;
        CombatLevelTask combat = task instanceof CombatLevelTask ? (CombatLevelTask) task : null;
        QuestPointsTask questPoints = task instanceof QuestPointsTask ? (QuestPointsTask) task : null;
        int target = item != null ? item.getQuantity()
            : combat != null ? 1
            : questPoints != null ? questPoints.getTargetQuestPoints()
            : level ? ((SkillLevelTask) task).getTargetSkillLevel() : ((SkillXpTask) task).getTargetSkillXp();
        String name = item != null ? item.getItemName()
            : combat != null ? "Combat"
            : questPoints != null ? "Quest points"
            : (level ? ((SkillLevelTask) task).getSkill() : ((SkillXpTask) task).getSkill()).getName();
        fields.add(new JLabel(name), BorderLayout.NORTH);
        SkillTargetFields skillTarget = new SkillTargetFields();
        JSpinner quantity = createQuantitySpinner(item == null ? 1 : target);
        JSpinner combatTarget = combat == null ? null : createCombatLevelSpinner(combat.getTargetCombatLevel());
        JSpinner questPointsTarget = questPoints == null ? null : createQuestPointsSpinner(target);
        if (item != null)
        {
            JPanel quantityRow = new JPanel(new BorderLayout(8, 0));
            quantityRow.add(new JLabel("Quantity"), BorderLayout.WEST);
            quantityRow.add(quantity, BorderLayout.CENTER);
            fields.add(quantityRow, BorderLayout.CENTER);
        }
        else if (combat != null)
        {
            JPanel combatRow = new JPanel(new BorderLayout(8, 0));
            combatRow.add(new JLabel("Combat level (3–126)"), BorderLayout.WEST);
            combatRow.add(combatTarget, BorderLayout.CENTER);
            fields.add(combatRow, BorderLayout.CENTER);
        }
        else if (questPoints != null)
        {
            JPanel questPointsRow = new JPanel(new BorderLayout(8, 0));
            questPointsRow.add(new JLabel("Target quest points"), BorderLayout.WEST);
            questPointsRow.add(questPointsTarget, BorderLayout.CENTER);
            fields.add(questPointsRow, BorderLayout.CENTER);
        }
        else
        {
            if (task instanceof SkillXpTask && ((SkillXpTask) task).getTargetLevel() != null)
                skillTarget.setLevelTarget(((SkillXpTask) task).getTargetLevel());
            else if (level) skillTarget.setLevelTarget(target);
            else skillTarget.setXpTarget(target);
            fields.add(skillTarget, BorderLayout.CENTER);
        }
        JButton cancel = new JButton("Cancel");
        JButton save = new JButton("Save");
        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 0));
        buttons.add(cancel);
        buttons.add(save);
        fields.add(buttons, BorderLayout.SOUTH);
        cancel.addActionListener(e -> dialog.dispose());
        save.addActionListener(e -> {
            final int value;
            try
            {
                if (item != null) quantity.commitEdit();
                if (combat != null) combatTarget.commitEdit();
                if (questPoints != null) questPointsTarget.commitEdit();
                value = item != null ? (Integer) quantity.getValue()
                    : questPoints != null ? (Integer) questPointsTarget.getValue()
                    : skillTarget.isLevelTarget() ? skillTarget.getTargetLevel() : skillTarget.getTargetXp();
            }
            catch (IllegalArgumentException | ArithmeticException | java.text.ParseException ex)
            {
                String message = item != null
                    ? "Enter a whole number from 1 to " + Integer.MAX_VALUE + ". You can use k or m."
                    : questPoints != null ? "Enter a whole number from " + QuestPointsTask.MIN_QUEST_POINTS + " to " + QuestPointsTask.MAX_QUEST_POINTS + "."
                    : combat != null ? "Enter a combat level from 3 to 126, with up to two decimal places."
                    : "Enter a level from 1 to 127 (up to two decimal places) or XP from 0 to 200M (k/m allowed).";
                JOptionPane.showMessageDialog(dialog, message, "Invalid target", JOptionPane.ERROR_MESSAGE);
                return;
            }
            if (!goal.getTasks().contains(task) || !plugin.getGoalManager().getGoals().contains(goal))
            {
                dialog.dispose();
                return;
            }
            boolean wasCompleted = task.getStatus().isCompleted();
            if (item != null)
            {
                item.setQuantity(value);
                item.recomputeFromCount(item.getAcquired());
            }
            else if (questPoints != null)
            {
                questPoints.setTargetQuestPoints(value);
                questPoints.setStatus(questPoints.hasReachedTarget() ? Status.COMPLETED
                    : questPoints.getCurrentQuestPoints() > 0 ? Status.IN_PROGRESS : Status.NOT_STARTED);
            }
            else if (combat != null)
            {
                combat.setTargetCombatLevel(((Number) combatTarget.getValue()).doubleValue());
                combat.setStatus(combat.hasReachedTargetLevel() ? Status.COMPLETED : Status.NOT_STARTED);
            }
            Task savedTask = task;
            if (item == null && combat == null && questPoints == null)
            {
                savedTask = retargetSkill(task, skillTarget.isLevelTarget(), value);
                if (savedTask instanceof SkillXpTask)
                    ((SkillXpTask) savedTask).setTargetLevel(skillTarget.getEnteredLevel());
                if (savedTask != task)
                {
                    goal.getTasks().set(goal.getTasks().indexOf(task), savedTask);
                    GoalPanel panel = (GoalPanel) SwingUtilities.getAncestorOfClass(GoalPanel.class, parent);
                    if (panel != null) panel.refreshTaskList();
                }
            }
            savedTask.setNotified(false);
            plugin.getGoalManager().save();
            plugin.getUiStatusManager().refresh(savedTask);
            plugin.getUiStatusManager().refresh(goal);
            plugin.refreshEditedTask(savedTask, goal, wasCompleted);
            dialog.dispose();
        });
        dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        dialog.setContentPane(fields);
        dialog.getRootPane().setDefaultButton(save);
        dialog.getRootPane().registerKeyboardAction(e -> dialog.dispose(), KeyStroke.getKeyStroke("ESCAPE"), JComponent.WHEN_IN_FOCUSED_WINDOW);
        dialog.pack();
        dialog.setLocationRelativeTo(parent);
        dialog.setVisible(true);
    }

    static JSpinner createQuestPointsSpinner(int value)
    {
        JSpinner spinner = QuestPointsTaskInput.createTargetSpinner(value);
        QuestPointsTaskInput.configureEditor(spinner);
        return spinner;
    }
}

