    static void applyStatus(Task task, Status status)
    {
        task.setStatus(status);
        if (status != Status.COMPLETED && task instanceof ItemTask)
        {
            ItemTask itemTask = (ItemTask) task;
            itemTask.updateAcquiredFromCount(itemTask.getTotalInventoryQuantity());
        }
    }

    private void addEditMenuItem()
    {
        if (taskContent != null && taskContent.canEditTarget())
        {
            JMenuItem edit = new JMenuItem("Edit");
            edit.addActionListener(e -> taskContent.editTarget());
            popupMenu.add(edit);
        }
    }

    private void refreshParentList()
    {
        Container parent = SwingUtilities.getAncestorOfClass(ListPanel.class, this);
        if (parent instanceof ListPanel) {
            ((ListPanel<?>) parent).tryBuildList();
            ((ListPanel<?>) parent).refresh();
        } else {
            // Fallback
            revalidate();
            repaint();
        }
    }

    private void addParentMenuItems()
    {
        java.util.List<Task> descendants = TaskHierarchyUtils.getDescendants(list, item);
        java.util.List<Task> candidates = new java.util.ArrayList<>();
        for (Task candidate : list)
            if (candidate != item && !descendants.contains(candidate)) candidates.add(candidate);
        JMenuItem setParent = new JMenuItem("Set parent...");
        setParent.setEnabled(!candidates.isEmpty());
        setParent.addActionListener(e -> startParentSelection(candidates));
        popupMenu.add(setParent);
        if (item.getParentTaskId() != null) {
            JMenuItem removeParent = new JMenuItem("Remove parent");
            removeParent.addActionListener(e -> removeParent());
            popupMenu.add(removeParent);
        }
    }

    void startParentSelection(List<Task> candidates)
    {
        if (interactionState.getMode() == TaskInteractionState.Mode.SET_PARENT) return;
        ParentSelectionMode selection = new ParentSelectionMode(this, candidates);
        selection.start();
    }

    String getInvalidParentReason(Task candidate)
    {
        if (candidate == item || java.util.Objects.equals(candidate.getTaskId(), item.getTaskId()))
            return "Can't select itself as its parent.";
        if (java.util.Objects.equals(candidate.getTaskId(), item.getParentTaskId()))
            return "Already the parent.";
        if (TaskHierarchyUtils.getDescendants(list, item).contains(candidate))
            return "Can't make a child the parent.";
        if (!TaskHierarchyUtils.canSetParent(list, item, candidate))
            return "This would exceed the maximum hierarchy depth.";
        return null;
    }

    private boolean isValidParentCandidate(Task candidate)
    {
        return getInvalidParentReason(candidate) == null;
    }

    static String formatParentSelectionTooltip(String status)
    {
        return "<html>" + status + "<br>Right click or Escape to cancel.</html>";
    }

    static BufferedImage createPlusCursorImage(int width, int height)
    {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        int dimensionParity = Math.min(width, height) % 2;
        int armLength = Math.min(16, Math.min(width, height) - 4);
        if (armLength % 2 != dimensionParity) armLength--;
        int barWidth = dimensionParity == 0 ? 4 : 3;
        int outlineArmLength = Math.min(Math.min(width, height), armLength + 4);
        int outlineBarWidth = Math.min(Math.min(width, height), barWidth + 4);
        drawCenteredPlus(graphics, width, height, outlineArmLength, outlineBarWidth, new Color(20, 30, 20));
        drawCenteredPlus(graphics, width, height, armLength, barWidth, new Color(60, 230, 90));
        graphics.dispose();
        return image;
    }

    private static void drawCenteredPlus(Graphics2D graphics, int width, int height,
                                         int armLength, int barWidth, Color color)
    {
        graphics.setColor(color);
        graphics.fillRect((width - barWidth) / 2, (height - armLength) / 2, barWidth, armLength);
        graphics.fillRect((width - armLength) / 2, (height - barWidth) / 2, armLength, barWidth);
    }

    /** Temporary window-level interaction that lets the player choose a visible task as parent. */
    private static final class ParentSelectionMode implements AWTEventListener
    {
        private static final String ESCAPE_ACTION_KEY = "goaltracker.cancelParentSelection";
        private static final Cursor ADD_CURSOR = createAddCursor();
        private static final Cursor INVALID_CURSOR = createInvalidCursor();
        private static final Color VALID_HIGHLIGHT = new Color(40, 200, 70, 80);
        private static final Color INVALID_HIGHLIGHT = new Color(220, 45, 45, 85);

        private final ListTaskPanel source;
        private final List<Task> candidates;
        private final List<ListTaskPanel> taskRows;
        private ListTaskPanel hovered;
        private final Map<Component, Cursor> sourceCursors;
        private final String sourceToolTip;
        private Map<Component, Cursor> hoveredCursors;
        private Map<JComponent, String> hoveredToolTips;
        private boolean active;
        private boolean deferInteractionReset;
        private boolean swallowRightClickRelease;
        private ListTaskPanel pressedInvalidTarget;
        private InputMap escapeInputMap;
        private ActionMap escapeActionMap;
        private Object previousEscapeBinding;
        private Action previousEscapeAction;
        private boolean hadLocalEscapeBinding;
        private boolean hadLocalEscapeAction;

        private ParentSelectionMode(ListTaskPanel source, List<Task> candidates)
        {
            this.source = source;
            this.candidates = new ArrayList<>(candidates);
            this.taskRows = collectTaskRows(source);
            this.sourceCursors = captureCursors(source);
            this.sourceToolTip = source.getToolTipText();
        }

        private void start()
        {
            active = true;
            source.interactionState.beginParentSelection(source.item);
            taskRows.forEach(row -> row.setContextMenuSuppressed(true));
            Toolkit.getDefaultToolkit().addAWTEventListener(this,
                    AWTEvent.MOUSE_MOTION_EVENT_MASK | AWTEvent.MOUSE_EVENT_MASK);
            installEscapeBinding();
            setCursorRecursively(source, ADD_CURSOR);
            source.setToolTipText("Choose a task to become the parent. Right-click or press Escape to cancel.");
        }

        @Override
        public void eventDispatched(AWTEvent event)
        {
            if (!(event instanceof MouseEvent)) return;
            MouseEvent mouse = (MouseEvent) event;
            if (swallowRightClickRelease)
            {
                if (mouse.getID() == MouseEvent.MOUSE_PRESSED && SwingUtilities.isRightMouseButton(mouse))
                {
                    mouse.consume();
                    return;
                }
                if (mouse.getID() == MouseEvent.MOUSE_RELEASED && SwingUtilities.isRightMouseButton(mouse))
                {
                    mouse.consume();
                    swallowRightClickRelease = false;
                    Toolkit.getDefaultToolkit().removeAWTEventListener(this);
                    SwingUtilities.invokeLater(() -> {
                        source.interactionState.endParentSelection();
                        restoreContextMenus();
                    });
                }
                return;
            }
            if (!active) return;
            Component component = mouse.getSource() instanceof Component ? (Component) mouse.getSource() : null;
            ListTaskPanel target = component instanceof ListTaskPanel ? (ListTaskPanel) component
                    : component == null ? null
                    : (ListTaskPanel) SwingUtilities.getAncestorOfClass(ListTaskPanel.class, component);

            if (mouse.getID() == MouseEvent.MOUSE_MOVED || mouse.getID() == MouseEvent.MOUSE_DRAGGED)
            {
                if (target != null && target.list == source.list)
                {
                    setHovered(target);
                }
                else if (pressedInvalidTarget == null)
                {
                    setHovered(null);
                }
                return;
            }

            if (mouse.getID() == MouseEvent.MOUSE_RELEASED)
            {
                if (target != null && target.list == source.list) setHovered(target);
                pressedInvalidTarget = null;
                return;
            }

            if (mouse.getID() != MouseEvent.MOUSE_PRESSED) return;
            if (SwingUtilities.isRightMouseButton(mouse))
            {
                mouse.consume();
                deferInteractionReset = true;
                swallowRightClickRelease = true;
                finish();
            }
            else if (SwingUtilities.isLeftMouseButton(mouse))
            {
                mouse.consume();
                if (target != null && target.list == source.list)
                {
                    boolean valid = candidates.contains(target.item) && source.isValidParentCandidate(target.item);
                    setHovered(target);
                    pressedInvalidTarget = valid ? null : target;
                }
                if (target != null && target.list == source.list && candidates.contains(target.item)
                        && source.isValidParentCandidate(target.item))
                {
                    ListTaskPanel selected = target;
                    deferInteractionReset = true;
                    finish();
                    SwingUtilities.invokeLater(() -> {
                        source.interactionState.endParentSelection();
                        restoreContextMenus();
                    });
                    source.changeParent(selected.item.getTaskId());
                }
            }
        }

        private void installEscapeBinding()
        {
            escapeInputMap = source.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW);
            escapeActionMap = source.getActionMap();
            KeyStroke escape = KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0);
            hadLocalEscapeBinding = escapeInputMap.keys() != null
                    && java.util.Arrays.asList(escapeInputMap.keys()).contains(escape);
            previousEscapeBinding = escapeInputMap.get(escape);
            hadLocalEscapeAction = escapeActionMap.keys() != null
                    && java.util.Arrays.asList(escapeActionMap.keys()).contains(ESCAPE_ACTION_KEY);
            previousEscapeAction = escapeActionMap.get(ESCAPE_ACTION_KEY);
            escapeInputMap.put(escape, ESCAPE_ACTION_KEY);
            escapeActionMap.put(ESCAPE_ACTION_KEY, new AbstractAction()
            {
                @Override
                public void actionPerformed(ActionEvent event)
                {
                    cancel();
                }
            });
        }

        private void removeEscapeBinding()
        {
            if (escapeInputMap == null) return;
            KeyStroke escape = KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0);
            if (hadLocalEscapeBinding) escapeInputMap.put(escape, previousEscapeBinding);
            else escapeInputMap.remove(escape);
            if (hadLocalEscapeAction) escapeActionMap.put(ESCAPE_ACTION_KEY, previousEscapeAction);
            else escapeActionMap.remove(ESCAPE_ACTION_KEY);
            escapeInputMap = null;
            escapeActionMap = null;
        }

        private void setHovered(ListTaskPanel next)
        {
            if (hovered == next) return;
            if (hovered != null)
            {
                hovered.setParentSelectionOverlay(null);
                restoreCursors(hoveredCursors);
                restoreToolTips(hoveredToolTips);
            }
            hovered = next;
            if (hovered != null)
            {
                String invalidReason = source.getInvalidParentReason(hovered.item);
                boolean valid = candidates.contains(hovered.item) && invalidReason == null;
                hovered.setParentSelectionOverlay(valid ? VALID_HIGHLIGHT : INVALID_HIGHLIGHT);
                hoveredCursors = captureAndSetCursors(hovered, valid ? ADD_CURSOR : INVALID_CURSOR);
                hoveredToolTips = captureAndSetToolTips(hovered,
                        formatParentSelectionTooltip(valid ? "Valid target."
                                : invalidReason == null ? "Not an eligible parent." : invalidReason));
            }
        }

        private void cancel()
        {
            finish();
        }

        private void finish()
        {
            if (!active) return;
            active = false;
            setHovered(null);
            if (!swallowRightClickRelease) Toolkit.getDefaultToolkit().removeAWTEventListener(this);
            removeEscapeBinding();
            restoreCursors(sourceCursors);
            if (!deferInteractionReset)
            {
                source.interactionState.endParentSelection();
                restoreContextMenus();
            }
            source.setToolTipText(sourceToolTip);
        }

        private void restoreContextMenus()
        {
            taskRows.forEach(row -> row.setContextMenuSuppressed(false));
        }

        private static List<ListTaskPanel> collectTaskRows(ListTaskPanel source)
        {
            Container listPanel = SwingUtilities.getAncestorOfClass(ListPanel.class, source);
            List<ListTaskPanel> rows = new ArrayList<>();
            if (listPanel != null) collectTaskRows(listPanel, rows);
            if (!rows.contains(source)) rows.add(source);
            return rows;
        }

        private static void collectTaskRows(Component component, List<ListTaskPanel> rows)
        {
            if (component instanceof ListTaskPanel) rows.add((ListTaskPanel) component);
            if (component instanceof Container)
                for (Component child : ((Container) component).getComponents()) collectTaskRows(child, rows);
        }

        private static Map<Component, Cursor> captureAndSetCursors(Component root, Cursor cursor)
        {
            Map<Component, Cursor> originals = captureCursors(root);
            setCursorRecursively(root, cursor);
            return originals;
        }

        private static Map<JComponent, String> captureAndSetToolTips(Component root, String toolTip)
        {
            Map<JComponent, String> originals = new IdentityHashMap<>();
            setToolTipRecursively(root, toolTip, originals);
            return originals;
        }

        private static void setToolTipRecursively(Component component, String toolTip,
                                                  Map<JComponent, String> originals)
        {
            if (component instanceof JComponent)
            {
                JComponent swingComponent = (JComponent) component;
                originals.put(swingComponent, swingComponent.getToolTipText());
                swingComponent.setToolTipText(toolTip);
            }
            if (component instanceof Container)
            {
                for (Component child : ((Container) component).getComponents())
                    setToolTipRecursively(child, toolTip, originals);
            }
        }

        private static void restoreToolTips(Map<JComponent, String> originals)
        {
            if (originals == null) return;
            originals.forEach(JComponent::setToolTipText);
        }

        private static Map<Component, Cursor> captureCursors(Component root)
        {
            Map<Component, Cursor> cursors = new IdentityHashMap<>();
            captureCursors(root, cursors);
            return cursors;
        }

        private static void captureCursors(Component component, Map<Component, Cursor> cursors)
        {
            cursors.put(component, component.getCursor());
            if (component instanceof Container)
                for (Component child : ((Container) component).getComponents()) captureCursors(child, cursors);
        }

        private static void setCursorRecursively(Component component, Cursor cursor)
        {
            component.setCursor(cursor);
            if (component instanceof Container)
                for (Component child : ((Container) component).getComponents()) setCursorRecursively(child, cursor);
        }

        private static void restoreCursors(Map<Component, Cursor> cursors)
        {
            if (cursors != null) cursors.forEach(Component::setCursor);
        }

        private static Cursor createAddCursor()
        {
            return createSymbolCursor(false);
        }

        private static Cursor createInvalidCursor()
        {
            return createSymbolCursor(true);
        }

        private static Cursor createSymbolCursor(boolean invalid)
        {
            try
            {
                Dimension size = Toolkit.getDefaultToolkit().getBestCursorSize(24, 24);
                if (size.width == 0 || size.height == 0) return Cursor.getPredefinedCursor(Cursor.CROSSHAIR_CURSOR);
                BufferedImage image;
                if (invalid)
                {
                    image = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
                    Graphics2D graphics = image.createGraphics();
                    graphics.setColor(new Color(20, 30, 20));
                    graphics.setStroke(new BasicStroke(5, BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER));
                    graphics.drawLine(5, 5, 18, 18);
                    graphics.drawLine(18, 5, 5, 18);
                    graphics.setColor(new Color(245, 55, 55));
                    graphics.setStroke(new BasicStroke(3, BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER));
                    graphics.drawLine(5, 5, 18, 18);
                    graphics.drawLine(18, 5, 5, 18);
                    graphics.dispose();
                }
                else
                {
                    image = createPlusCursorImage(size.width, size.height);
                }
                Point hotSpot = invalid ? new Point(12, 12)
                        : new Point((size.width - 1) / 2, (size.height - 1) / 2);
                return Toolkit.getDefaultToolkit().createCustomCursor(image, hotSpot,
                        invalid ? "InvalidParentCursor" : "SetParentCursor");
            }
            catch (RuntimeException e)
            {
                return Cursor.getPredefinedCursor(Cursor.CROSSHAIR_CURSOR);
            }
        }
    }

    void removeParent()
    {
        Task oldParent = TaskHierarchyUtils.getParent(list, item);
        Task newParent = oldParent == null ? null : TaskHierarchyUtils.getParent(list, oldParent);
        changeParent(newParent == null ? null : newParent.getTaskId(), oldParent, true);
    }

    void changeParent(String newParentId)
    {
        changeParent(newParentId, null, false);
    }

    private void changeParent(String newParentId, Task positionAnchor, boolean afterAnchorSubtree)
    {
        String oldParentId = item.getParentTaskId();
        if (java.util.Objects.equals(oldParentId, newParentId)) return;
        Task newParent = null;
        if (newParentId != null)
        {
            for (Task candidate : list)
                if (newParentId.equals(candidate.getTaskId())) { newParent = candidate; break; }
            if (newParent == null || !isValidParentCandidate(newParent)) return;
        }
        final Task destinationParent = newParent;
        java.util.List<Task> oldOrder = new java.util.ArrayList<>(list);
        java.util.List<Task> subtree = TaskHierarchyUtils.getSubtree(list, item);
        ActionHistory.Action action = new ActionHistory.Action() {
            @Override public void undo() {
                item.setParentTaskId(oldParentId);
                list.clear();
                list.addAll(oldOrder);
                TaskHierarchyUtils.normalizeIndentLevels(list);
            }
            @Override public void redo() {
                item.setParentTaskId(newParentId);
                if (destinationParent != null || positionAnchor != null)
                {
                    list.removeAll(subtree);
                    int insertIndex;
                    if (afterAnchorSubtree && positionAnchor != null)
                    {
                        int anchorIndex = list.indexOf(positionAnchor);
                        insertIndex = anchorIndex < 0 ? list.size() : anchorIndex + 1;
                        for (Task descendant : TaskHierarchyUtils.getDescendants(list, positionAnchor))
                        {
                            insertIndex = Math.max(insertIndex, list.indexOf(descendant) + 1);
                        }
                    }
                    else if (destinationParent != null)
                    {
                        insertIndex = list.indexOf(destinationParent) + 1;
                        for (Task descendant : TaskHierarchyUtils.getDescendants(list, destinationParent))
                            insertIndex = Math.max(insertIndex, list.indexOf(descendant) + 1);
                    }
                    else insertIndex = list.size();
                    list.addAll(insertIndex, subtree);
                }
                TaskHierarchyUtils.normalizeIndentLevels(list);
            }
        };
        if (history != null) { action.redo(); history.push(action); }
        else action.redo();
        if (parentChangedListener != null) parentChangedListener.accept(item);
        refreshParentList();
    }

    private void removeSubtree()
    {
        int removedIndex = list.indexOf(item);
        java.util.List<Task> subtree = TaskHierarchyUtils.getSubtree(list, item);
        if (subtree.isEmpty()) return;

        if (history != null)
        {
            RemoveTasksAction action = new RemoveTasksAction(list, subtree);
            action.redo();
            history.push(action);
        }
        else
        {
            for (int i = subtree.size() - 1; i >= 0; i--) list.remove(subtree.get(i));
        }

        if (this.removedWithIndexListener != null) this.removedWithIndexListener.accept(item, removedIndex);
        if (this.removedListener != null) this.removedListener.accept(item);
        refreshParentList();
    }

    /** Moves this row unless that would place it under a collapsed ancestor. */
    private int moveItemTo(int requestedIndex)
    {
        int oldIndex = list.indexOf(item);
        if (oldIndex < 0) return -1;

        list.remove(oldIndex);
        int newIndex = Math.max(0, Math.min(requestedIndex, list.size()));
        list.add(newIndex, item);
        if (TaskHierarchyUtils.hasCollapsedAncestor(list, item))
        {
            list.remove(newIndex);
            list.add(oldIndex, item);
            return -1;
        }
        return newIndex;
    }
    /**
     * Programmatically add quest prerequisites using the same logic as the context menu action.
     * This lets callers (e.g., presets) trigger prereq insertion without simulating a right-click.
     */
    public static void addPrereqsForTask(ReorderableList<Task> list, Task item)
    {
        if (!(item instanceof QuestTask)) {
            return;
        }
        QuestTask questTask = (QuestTask) item;
        int baseIndent = item.getIndentLevel();

        // Gather existing descendants under this task to avoid duplicates
        java.util.Set<String> existingKeys = new java.util.HashSet<>();
        for (Task child : TaskHierarchyUtils.getDescendants(list, item)) {
            existingKeys.add(child.getClass().getName() + "|" + child.toString());
        }

        java.util.List<Task> raw = QuestRequirements.getRequirements(questTask.getQuest(), baseIndent);
        if (raw == null || raw.isEmpty()) {
            return;
        }

        // Filter out any already-present entries
        java.util.List<Task> filtered = new java.util.ArrayList<>();
        for (Task t : raw) {
            String key = t.getClass().getName() + "|" + t.toString();
            if (!existingKeys.contains(key)) {
                filtered.add(t);
            }
        }

        if (filtered.isEmpty()) {
            return;
        }

        TaskHierarchyUtils.initializeFromIndent(filtered, baseIndent, item);

        // Insert directly after the parent item, preserving order from QuestRequirements
        int insertIndex = list.indexOf(item);
        for (Task prereq : filtered) {
            list.add(insertIndex + 1, prereq);
            insertIndex++;
        }
        TaskHierarchyUtils.normalizeIndentLevels(list);
    }
}

package com.darkforge317.goaltracker.ui.components;

import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.awt.*;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/** Skill dropdown using the same control and arrow icons as quest selection. */
public final class SkillSelector extends JPanel
{
    private final ComboBox<Skill> dropdown;

    public SkillSelector(SkillIconManager icons)
    {
        super(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        List<Skill> skills = Arrays.stream(Skill.values())
            .collect(Collectors.toList());
        dropdown = new ComboBox<>(skills);
        dropdown.setFont(new Font("RuneScape UF", Font.PLAIN, 10));
        dropdown.setBorder(BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR, 1));
        dropdown.getAccessibleContext().setAccessibleName("Choose a skill");
        ListCellRenderer<? super Skill> renderer = dropdown.getRenderer();
        dropdown.setRenderer((list, value, index, selected, focused) -> {
            JPanel row = (JPanel) renderer.getListCellRendererComponent(list, value, index, selected, focused);
            JLabel label = (JLabel) row.getComponent(0);
            label.setText(value == null ? "Choose a skill" : value.getName());
            label.setIcon(value == null ? null : new ImageIcon(icons.getSkillImage(value, true)));
            return row;
        });
        dropdown.setSelectedIndex(-1);
        add(dropdown, BorderLayout.CENTER);
    }

    public Skill getSelectedSkill()
    {
        return (Skill) dropdown.getSelectedItem();
    }

    public void setSelectedSkill(Skill skill)
    {
        if (skill != null)
        {
            boolean available = false;
            for (int i = 0; i < dropdown.getItemCount(); i++)
                if (dropdown.getItemAt(i) == skill) available = true;
            if (!available) throw new IllegalArgumentException("Choose a trainable skill");
        }
        dropdown.setSelectedItem(skill);
    }
}

package com.darkforge317.goaltracker.ui.components;

import com.darkforge317.goaltracker.ui.SimpleDocumentListener;
import net.runelite.api.Experience;

import javax.swing.*;
import java.awt.*;
import java.util.Locale;
import java.math.BigDecimal;
import javax.swing.text.*;

/** Two views of one target. The last edited field determines how the task is saved. */
public final class SkillTargetFields extends JPanel
{
    private final JTextField level = new JTextField(6);
    private final JTextField xp = new JTextField(10);
    private boolean syncing;
    private boolean levelTarget = true;

    public SkillTargetFields()
    {
        super(new GridBagLayout());
        setOpaque(false);
        GridBagConstraints constraints = new GridBagConstraints();
        constraints.insets = new Insets(2, 0, 2, 8);
        constraints.anchor = GridBagConstraints.WEST;
        add(new JLabel("Level"), constraints);
        constraints.gridx = 1;
        constraints.weightx = 1;
        constraints.fill = GridBagConstraints.HORIZONTAL;
        constraints.insets = new Insets(2, 0, 2, 0);
        level.setPreferredSize(new Dimension(120, 30));
        add(level, constraints);
        constraints.gridx = 0;
        constraints.gridy = 1;
        constraints.weightx = 0;
        constraints.insets = new Insets(2, 0, 2, 8);
        add(new JLabel("XP"), constraints);
        constraints.gridx = 1;
        constraints.weightx = 1;
        constraints.insets = new Insets(2, 0, 2, 0);
        xp.setPreferredSize(new Dimension(120, 30));
        add(xp, constraints);
        level.getAccessibleContext().setAccessibleName("Target level");
        xp.getAccessibleContext().setAccessibleName("Target XP");
        level.setToolTipText("Level 1–127; accepts up to two decimal places");
        xp.setToolTipText("XP 0–200M; accepts k/m suffixes; shows the corresponding level");
        ((AbstractDocument) level.getDocument()).setDocumentFilter(new TargetFilter(true));
        ((AbstractDocument) xp.getDocument()).setDocumentFilter(new TargetFilter(false));
        level.getDocument().addDocumentListener((SimpleDocumentListener) e -> sync(true));
        xp.getDocument().addDocumentListener((SimpleDocumentListener) e -> sync(false));
        setLevelTarget(99);
    }

    private void sync(boolean fromLevel)
    {
        if (syncing) return;
        levelTarget = fromLevel;
        try
        {
            int value = fromLevel ? xpForLevel(parseLevel(level.getText())) : parseXp(xp.getText());
            syncing = true;
            if (fromLevel) xp.setText(Integer.toString(value));
            else level.setText(BigDecimal.valueOf(levelForXp(value)).stripTrailingZeros().toPlainString());
        }
        catch (IllegalArgumentException ex) { /* Allow empty and incomplete input while typing. */ }
        finally { syncing = false; }
    }

    public static double parseLevel(String text)
    {
        if (!text.trim().matches("[0-9]+(\\.[0-9]{0,2})?")) throw new IllegalArgumentException("Enter a level from 1 to 127.");
        double value = Double.parseDouble(text.trim());
        if (value < 1 || value > 127) throw new IllegalArgumentException("Enter a level from 1 to 127.");
        return value;
    }

    // RuneLite's XP table ends at 126; the capped level-127 endpoint is 200M.
    private static int xpAtLevel(int value)
    {
        return value == 127 ? 200000000 : Experience.getXpForLevel(value);
    }

    public static int xpForLevel(double value)
    {
        int whole = (int) value;
        int lower = xpAtLevel(whole);
        if (whole == 127) return lower;
        return (int) Math.round(lower + (value - whole) * (xpAtLevel(whole + 1) - lower));
    }

    public static double levelForXp(int value)
    {
        int whole = 1;
        while (whole < 127 && xpAtLevel(whole + 1) <= value) whole++;
        if (whole == 127) return 127;
        double fraction = (double) (value - xpAtLevel(whole))
            / (xpAtLevel(whole + 1) - xpAtLevel(whole));
        return Math.round((whole + fraction) * 100) / 100.0;
    }

    /** Reject unsupported syntax and clamp bounds before text reaches the document. */
    private final class TargetFilter extends DocumentFilter
    {
        private final boolean forLevel;
        private TargetFilter(boolean forLevel) { this.forLevel = forLevel; }
        @Override public void insertString(FilterBypass fb, int offset, String text, AttributeSet attrs)
            throws BadLocationException { replace(fb, offset, 0, text, attrs); }
        @Override public void remove(FilterBypass fb, int offset, int length)
            throws BadLocationException { replace(fb, offset, length, "", null); }
        @Override public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attrs)
            throws BadLocationException
        {
            String old = fb.getDocument().getText(0, fb.getDocument().getLength());
            String value = old.substring(0, offset) + (text == null ? "" : text) + old.substring(offset + length);
            String candidate = value;
            if (!syncing && !value.isEmpty())
            {
                if (!value.matches(forLevel ? "-?[0-9]+(\\.[0-9]{0,2})?" : "-?[0-9]+[kKmM]?")) return;
                String numeric = value.replaceAll("[kKmM]$", "");
                BigDecimal number = new BigDecimal(numeric);
                if (!forLevel && value.toLowerCase(Locale.ROOT).endsWith("k")) number = number.multiply(BigDecimal.valueOf(1000));
                if (!forLevel && value.toLowerCase(Locale.ROOT).endsWith("m")) number = number.multiply(BigDecimal.valueOf(1000000));
                int min = forLevel ? 1 : 0;
                int max = forLevel ? 127 : 200000000;
                if (number.compareTo(BigDecimal.valueOf(min)) < 0) value = Integer.toString(min);
                if (number.compareTo(BigDecimal.valueOf(max)) > 0) value = Integer.toString(max);
            }
            if (value.equals(candidate)) fb.replace(offset, length, text, attrs);
            else fb.replace(0, old.length(), value, attrs);
        }
    }

    public static int parseXp(String text)
    {
        String value = text.trim().toLowerCase(Locale.ROOT);
        if (!value.matches("[0-9]+[km]?")) throw new IllegalArgumentException("Enter XP from 0 to 200M (k/m allowed).");
        int multiplier = value.endsWith("k") ? 1000 : value.endsWith("m") ? 1000000 : 1;
        if (multiplier != 1) value = value.substring(0, value.length() - 1);
        long number = Long.parseLong(value);
        if (number > 200000000L / multiplier) throw new IllegalArgumentException("Enter XP from 0 to 200M.");
        return (int) (number * multiplier);
    }

    /** Fractional and virtual targets use XP tasks so progress and completion remain exact. */
    public boolean isLevelTarget()
    {
        if (!levelTarget) return false;
        double value = parseLevel(level.getText());
        return value <= 99 && value == Math.floor(value);
    }
    /** Only whole virtual milestones retain a level title on an XP task. */
    public Double getEnteredLevel()
    {
        if (!levelTarget) return null;
        double value = parseLevel(level.getText());
        return value > 99 && value == Math.floor(value) ? value : null;
    }
    public int getTargetLevel() { return (int) parseLevel(level.getText()); }
    public int getTargetXp()
    {
        return levelTarget ? xpForLevel(parseLevel(level.getText())) : parseXp(xp.getText());
    }
    public void setLevelTarget(double value) { level.setText(BigDecimal.valueOf(value).stripTrailingZeros().toPlainString()); }
    public void setXpTarget(int value) { xp.setText(Integer.toString(value)); }
}

package com.darkforge317.goaltracker.ui.components;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;

/**
 * Small clickable label styled as a button, used for text-based actions.
 * Supports hover effects and consumer-based click listeners.
 */
public final class TextButton extends JLabel
{
    private Color mainColor = ColorScheme.PROGRESS_COMPLETE_COLOR;
    private boolean hoverEffectsEnabled = true;

    public void setHoverEffectsEnabled(boolean enabled)
    {
        hoverEffectsEnabled = enabled;
        if (!enabled) setForeground(mainColor);
    }

    public TextButton(String text, Color mainColor)
    {
        this(text);
        setMainColor(mainColor);
    }

    public TextButton(String text)
    {
        super(text);

        setFont(FontManager.getRunescapeSmallFont());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(new EmptyBorder(0, 8, 0, 8));
        setForeground(mainColor);
    }

    public TextButton setMainColor(Color mainColor)
    {
        this.mainColor = mainColor;
        setForeground(mainColor);
        return this;
    }

    public TextButton(String text, Consumer<MouseEvent> clickListener)
    {
        this(text);
        onClick(clickListener);
    }

    public TextButton onClick(Consumer<MouseEvent> clickListener)
    {
        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                if (SwingUtilities.isLeftMouseButton(e)) clickListener.accept(e);
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                if (!hoverEffectsEnabled) return;
                setForeground(mainColor.darker());
                setCursor(new Cursor(Cursor.HAND_CURSOR));
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                if (!hoverEffectsEnabled) return;
                setForeground(mainColor);
                setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
            }
        });
        return this;
    }

    public TextButton narrow()
    {
        setBorder(new EmptyBorder(0, 2, 0, 2));
        return this;
    }

    public void setOnClick(Object o) {
    }
}

package com.darkforge317.goaltracker.ui.inputs;

import com.darkforge317.goaltracker.GoalTrackerPlugin;
import com.darkforge317.goaltracker.models.Goal;
import com.darkforge317.goaltracker.models.task.CombatLevelTask;

import javax.swing.JSpinner;
import javax.swing.SwingConstants;
import javax.swing.SpinnerNumberModel;
import java.awt.BorderLayout;

/** Input for creating a combat-level goal. */
public final class CombatLevelTaskInput extends TaskInput
{
    static final int MIN_COMBAT_LEVEL = 3;
    static final int MAX_COMBAT_LEVEL = 126;
    static final double COMBAT_LEVEL_STEP = 0.25;

    private final JSpinner target = new JSpinner(new SpinnerNumberModel(
        (double) MAX_COMBAT_LEVEL, (double) MIN_COMBAT_LEVEL, (double) MAX_COMBAT_LEVEL, COMBAT_LEVEL_STEP)
    {
        @Override public void setValue(Object value)
        {
            if (!(value instanceof Number))
            {
                throw new IllegalArgumentException("Combat level must be between 3 and 126.");
            }
            Number number = (Number) value;
            double target = number.doubleValue();
            if (!Double.isFinite(target) || target < MIN_COMBAT_LEVEL || target > MAX_COMBAT_LEVEL
                || Math.abs(target * 100 - Math.rint(target * 100)) > 0.000001)
            {
                throw new IllegalArgumentException("Combat level must be between 3 and 126, with at most two decimal places.");
            }
            super.setValue(target);
        }
    });

    public CombatLevelTaskInput(GoalTrackerPlugin plugin, Goal goal)
    {
        super(plugin, goal, "Combat level");
        JSpinner.NumberEditor editor = new JSpinner.NumberEditor(target, "0.00");
        editor.getTextField().setColumns(5);
        editor.getTextField().setHorizontalAlignment(SwingConstants.LEFT);
        target.setEditor(editor);
        target.setToolTipText("Combat level 3–126; up to two decimal places");
        getInputRow().add(target, BorderLayout.CENTER);
    }

    @Override
    protected void submit()
    {
        addTask(CombatLevelTask.builder().targetCombatLevel(((Number) target.getValue()).doubleValue()).build());
    }

    @Override
    protected void reset()
    {
        target.setValue(MAX_COMBAT_LEVEL);
    }

    JSpinner getTargetSpinner()
    {
        return target;
    }
}

package com.darkforge317.goaltracker.ui.inputs;

import com.darkforge317.goaltracker.GoalTrackerPlugin;
import com.darkforge317.goaltracker.models.Goal;
import com.darkforge317.goaltracker.models.task.ItemTask;
import com.darkforge317.goaltracker.ui.components.TextButton;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.text.ParseException;
import java.util.Locale;

/** Item selection and quantity preview, submitted explicitly with Add. */
public final class ItemTaskInput extends TaskInput
{
    private final JSpinner quantityField = new JSpinner(new SpinnerNumberModel(1, 1, Integer.MAX_VALUE, 1));
    private final TextButton searchItemButton = new TextButton("Search...");
    private final JLabel selectedItemLabel = new JLabel();
    private final JPanel selectedItemPanel = new JPanel(new BorderLayout());
    private boolean searchOpen;
    private ItemComposition selectedItem;
    private Window hiddenDialogForSearch;

    public ItemTaskInput(GoalTrackerPlugin plugin, Goal goal)
    {
        super(plugin, goal, "Item");
        searchItemButton.onClick(e -> {
            if (searchOpen) {
                plugin.getChatboxPanelManager().close();
                searchClosed();
                return;
            }
            if (plugin.getClient().getGameState() != GameState.LOGGED_IN) {
                JOptionPane.showMessageDialog(this, "You must be logged in to choose items",
                    "Item search", JOptionPane.ERROR_MESSAGE);
                return;
            }
            searchOpen = true;
            searchItemButton.setText("Close");
            hideDialogForSearch();
            ChatboxItemSearch itemSearch = plugin.getItemSearch();
            itemSearch
                .tooltipText("Choose an item")
                .onItemSelected(this::setSelectedItem)
                .onClose(() -> SwingUtilities.invokeLater(() -> {
                    searchClosed();
                    restoreDialogAfterSearch();
                }))
                .build();
            // Chatbox input opens asynchronously on the client thread. Request canvas focus
            // after RuneLite has processed that open request; unlike the standard Add Task
            // form, Add Child is in a separate dialog which is hidden while searching.
            plugin.getClientThread().invokeLater(() -> {
                SwingUtilities.invokeLater(() -> plugin.getClient().getCanvas().requestFocusInWindow());
            });
        });
        getInputRow().add(searchItemButton, BorderLayout.WEST);

        JSpinner.NumberEditor editor = new JSpinner.NumberEditor(quantityField, "0");
        quantityField.setEditor(editor);
        editor.getTextField().setFormatterFactory(new javax.swing.text.DefaultFormatterFactory(
            new JFormattedTextField.AbstractFormatter() {
                @Override
                public Object stringToValue(String text) throws ParseException
                {
                    return parseQuantity(text);
                }

                @Override
                public String valueToString(Object value)
                {
                    return value.toString();
                }
            }));
        editor.getTextField().setHorizontalAlignment(SwingConstants.RIGHT);
        quantityField.setToolTipText("Quantity (supports k and m)");
        quantityField.setPreferredSize(new Dimension(80, 24));
        getInputRow().add(quantityField, BorderLayout.CENTER);

        selectedItemPanel.setBorder(new EmptyBorder(0, 8, 0, 8));
        selectedItemPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        selectedItemPanel.add(selectedItemLabel, BorderLayout.CENTER);
        selectedItemPanel.add(new TextButton("X")
            .setMainColor(ColorScheme.PROGRESS_ERROR_COLOR)
            .onClick(e -> clearSelectedItem()), BorderLayout.EAST);
        // Keep long item names from crowding the quantity and Add controls.
        selectedItemPanel.setPreferredSize(new Dimension(110, 24));
    }

    static int parseQuantity(String text) throws ParseException
    {
        String value = text.trim().toLowerCase(Locale.ROOT);
        if (!value.matches("[0-9]+[km]?")) {
            throw new ParseException("Enter a positive quantity", 0);
        }
        long multiplier = value.endsWith("k") ? 1000 : value.endsWith("m") ? 1000000 : 1;
        if (multiplier != 1) {
            value = value.substring(0, value.length() - 1);
        }
        try {
            long number = Long.parseLong(value);
            if (number < 1 || number > Integer.MAX_VALUE / multiplier) {
                throw new NumberFormatException();
            }
            return (int) (number * multiplier);
        } catch (NumberFormatException e) {
            throw new ParseException("Quantity must be between 1 and " + Integer.MAX_VALUE, 0);
        }
    }

    private void searchClosed()
    {
        searchOpen = false;
        searchItemButton.setText("Search...");
    }

    private void hideDialogForSearch()
    {
        Window ancestor = SwingUtilities.getWindowAncestor(this);
        if (ancestor instanceof JDialog && ancestor.isVisible())
        {
            hiddenDialogForSearch = ancestor;
            ancestor.setVisible(false);
        }
    }

    private void restoreDialogAfterSearch()
    {
        Window dialog = hiddenDialogForSearch;
        hiddenDialogForSearch = null;
        if (dialog != null && dialog.isDisplayable())
        {
            dialog.setVisible(true);
        }
    }

    public void closeSearch()
    {
        if (!searchOpen)
        {
            return;
        }
        plugin.getChatboxPanelManager().close();
        searchClosed();
    }

    private void setSelectedItem(Integer rawId)
    {
        plugin.getClientThread().invokeLater(() -> {
            ItemComposition item = plugin.getItemManager().getItemComposition(
                plugin.getItemManager().canonicalize(rawId));
            SwingUtilities.invokeLater(() -> {
                selectedItem = item;
                selectedItemLabel.setText(item.getName());
                selectedItemLabel.setToolTipText(item.getName());
                searchClosed();
                getInputRow().remove(searchItemButton);
                getInputRow().add(selectedItemPanel, BorderLayout.WEST);
                revalidate();
                repaint();
                ((JSpinner.DefaultEditor) quantityField.getEditor()).getTextField().requestFocusInWindow();
            });
        });
    }

    @Override
    protected void submit()
    {
        if (selectedItem == null) {
            return;
        }
        try {
            quantityField.commitEdit();
        } catch (ParseException e) {
            ((JSpinner.DefaultEditor) quantityField.getEditor()).getTextField().requestFocusInWindow();
            return;
        }
        addTask(ItemTask.builder()
            .itemId(selectedItem.getId())
            .itemName(selectedItem.getName())
            .quantity((Integer) quantityField.getValue())
            .build());
    }

    @Override
    protected void reset()
    {
        clearSelectedItem();
        quantityField.setValue(1);
    }

    private void clearSelectedItem()
    {
        selectedItem = null;
        getInputRow().remove(selectedItemPanel);
        getInputRow().add(searchItemButton, BorderLayout.WEST);
        searchClosed();
        revalidate();
        repaint();
    }
}

