            assertEquals(3000, task.getQuantity());
            assertEquals(1, quantity.getValue());
            input[0].submit();
            assertEquals(1, goal.getTasks().size());
        });
        verify(manager).canonicalize(101);
        verify(manager).getItemComposition(100);
    }
}

